const top_zaahen = {
  champion: '자헨',
  lane: 'top',
  patch: '26.22',
  matchups: {
    '가렌': { lv1: '가렌은 (Q)\'결정타\'로 이동 속도를 높여 접근하고 침묵을 걸며, 맞지 않는 동안 (P)\'인내심\'으로 체력을 회복해요. 1~2레벨에는 (Q)\'다르킨의 글레이브\'로 가렌의 체력을 깎으면서 본인의 체력을 회복하며 버티세요. 가렌이 (Q)\'결정타\'를 쓰고 달려올 때는 (W)\'공포의 귀환\'으로 가렌을 끌어당겨 대응하며 무리한 교환은 피하세요.', lv3: '가렌의 (Q)\'결정타\' 침묵에 걸리면 스킬을 쓸 수 없으니, 침묵이 풀린 직후 (Q)\'다르킨의 글레이브\'를 재사용해 가렌을 공중에 띄우며 딜교환을 시작하세요. 가렌이 (E)\'심판\'을 사용하며 회전할 때는 (E)\'찬란한 쇄도\'로 위치를 잡거나 (W)\'공포의 귀환\'을 활용해 대응하는 것이 좋아요. 가렌이 (W)\'용기\'를 켠 동안은 보호막이 생기고 받는 피해가 줄어드니, 효과가 끝난 뒤에 (Q)\'다르킨의 글레이브\'로 몰아치세요.', lv6: '가렌의 (R)\'데마시아의 정의\'는 체력이 낮을수록 강력하니 체력이 적을 때는 가렌 곁에서 멀리 떨어져야 해요. 가렌의 체력이 낮을 때 (R)\'단호한 판결\'을 사용하여 피해를 입히고 동시에 체력을 회복하며 승부를 보세요. 가렌이 (W)\'용기\'를 사용해 버틴다면 (E)\'찬란한 쇄도\'로 진입하여 빠르게 압박하는 것이 효과적이에요.', item: '첫 코어로 갈라진 하늘을 선택하면 공격력과 체력을 동시에 얻어 전투를 길게 이끌 수 있어요. 신발은 가렌의 기본 공격 피해를 줄여 주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화의 치유 감소 효과로 가렌의 (P)\'인내심\' 회복을 억제하면 킬을 따내기 편해요.' },
    '갱플랭크': { lv1: '갱플랭크는 (Q)\'혀어어어업상\'으로 멀리서 견제하며 골드를 챙기니 너무 가까이 있지 마세요. (Q)\'다르킨의 글레이브\'를 사용하여 체력을 회복하며 짧게 딜교환을 하세요. (P)\'불의 심판\'의 불이 붙은 상태로 오래 붙어 있으면 피해가 커지니 주의하세요.', lv3: '(E)\'화약통\'은 갱플랭크가 공격해서 터뜨릴 때 피해와 둔화를 주니 통 주변은 피하세요. (W)\'괴혈병 치료\'는 걸린 군중 제어 효과를 제거하니 그 스킬이 빠진 뒤에 (Q)\'다르킨의 글레이브\'를 재사용해 적을 공중에 띄우세요. (E)\'찬란한 쇄도\'로 빠르게 진입해 갱플랭크의 체력을 깎으세요.', lv6: '갱플랭크의 (R)\'포탄 세례\'가 깔리면 둔화가 걸리니 그 구역을 피해 (R)\'단호한 판결\'을 사용하세요. (W)\'괴혈병 치료\'를 쓰기 전에 (R)\'단호한 판결\'로 큰 피해를 입히고 체력을 회복하며 전투하세요. 갱플랭크가 (E)\'화약통\'을 터뜨리기 전에 (W)\'공포의 귀환\'으로 끌어당기면 킬을 내기 좋아요.', item: '판금 장화와 갈라진 하늘을 추천해요. 판금 장화는 갱플랭크의 기본 공격 피해를 줄여주고, 갈라진 하늘은 공격력과 체력을 주며 첫 기본 공격이 치명타로 적용되고 체력을 회복해요.', spell: '점멸과 점화를 추천해요. 점화로 갱플랭크의 (W)\'괴혈병 치료\' 회복량을 줄이면 킬을 내기 훨씬 쉬워요.' },
    '그라가스': { lv1: '그라가스는 (Q)\'술통 굴리기\'로 둔화를 걸며 견제하고 (P)\'서비스 시간\'으로 체력을 회복하니 주의하세요. (Q)\'다르킨의 글레이브\'를 활용해 맞딜을 하며 체력을 관리하고 술통이 터지는 위치를 잘 피하며 미니언을 챙기세요. 초반에는 무리한 진입보다는 거리 조절을 통해 체력을 보존하는 것이 중요해요.', lv3: '그라가스의 (E)\'몸통 박치기\'에 맞으면 공중에 뜨게 되니 이 스킬이 빠진 것을 확인하고 (W)\'공포의 귀환\'으로 진입하세요. 그라가스가 (W)\'취중 분노\'를 사용하면 받는 피해가 줄어드니 버프가 끝난 뒤에 (Q)\'다르킨의 글레이브\' 재사용으로 공중에 띄우며 싸우세요. 상대의 돌진기가 빠졌을 때 적극적으로 딜교환을 시도하는 것이 좋아요.', lv6: '그라가스가 (R)\'술통 폭발\'로 멀리 밀어낼 수 있으니 (R)\'단호한 판결\'을 사용할 때 위치 선정이 매우 중요해요. (R)\'단호한 판결\'로 적을 타격해 체력을 회복하며 킬각을 잡고, 정글러의 개입을 대비해 라인을 적절히 관리하세요. 만약 그라가스가 궁극기를 먼저 사용했다면 무리하게 쫓아가지 말고 거리를 벌려야 해요.', item: '첫 코어 아이템으로 체력과 공격력을 제공하는 갈라진 하늘을 선택하세요. 신발은 그라가스의 마법 피해를 줄여주고 (Q)\'술통 굴리기\' 둔화 지속시간을 줄여주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 점화는 그라가스의 (P)\'서비스 시간\'을 통한 체력 회복 효과를 감소시켜 킬각을 잡기 좋게 도와줘요.' },
    '그웬': { lv1: '그웬은 (P)\'가위 난도질\'의 체력 회복과 피해량이 상당하니 근접 교전을 길게 하지 마세요. 1~2레벨에는 (Q)\'다르킨의 글레이브\'로 빠르게 공격해 체력을 회복하고 빠지는 식으로 대응하세요. (Q)\'싹둑싹둑!\'의 중앙 고정 피해를 입지 않게 거리 조절에 신경 써야 해요.', lv3: '(W)\'신성한 안개\'는 대상 지정 스킬만 막으므로 지정 방향으로 내지르는 (W)\'공포의 귀환\'이나 주변을 가르는 (E)\'찬란한 쇄도\'는 그대로 맞힐 수 있어요. 그웬이 (E)\'돌격가위\'로 들어올 때 (W)\'공포의 귀환\'으로 끌어당긴 뒤 (Q)\'다르킨의 글레이브\'를 재사용해 공중에 띄우세요. 안개 속으로 직접 들어가서 공격하는 것이 효과적이에요.', lv6: '그웬의 (R)\'바느질\'에 맞으면 둔화되어 그웬이 거리를 벌리기 쉬우니 (R)\'단호한 판결\'의 피해 감소 효과로 버티며 진입하세요. (R)\'단호한 판결\'로 내려찍어 피해를 입히고 체력을 회복하며 전투를 이끄세요. (W)\'신성한 안개\'가 켜져 있을 때는 대상 지정이 안 되므로 반드시 안개 안으로 진입한 뒤 공격하세요.', item: '맬모셔스의 아귀를 첫 코어로 선택해 마법 저항력을 높이고 생명선 보호막으로 그웬의 피해를 견디세요. 신발은 마법 저항력과 (R)\'바느질\'의 둔화 지속시간을 줄여 주는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 점화를 추천해요. 그웬은 (P)\'가위 난도질\'로 챔피언을 공격할 때 체력을 회복하니 점화의 치유 감소로 이를 억제하세요.' },
    '나르': { lv1: '나르는 (Q)\'부메랑 던지기\'로 멀리서 견제하며 둔화를 걸어요. 부메랑이 돌아오는 궤적을 잘 보고 피해를 줄이면서 (Q)\'다르킨의 글레이브\'를 활용해 짧게 딜교환을 시도하세요. 1~2레벨에는 무리하게 들어가기보다 체력을 보존하며 맞서야 해요.', lv3: '나르의 분노가 차서 메가 나르로 변하면 (W)\'쿵쾅\'에 기절할 수 있으니 주의하세요. (W)\'공포의 귀환\'으로 나르를 끌어당긴 뒤 (Q)\'다르킨의 글레이브\'를 재사용해 공중에 띄우며 몰아치세요. 나르가 (E)\'폴짝\'으로 거리를 벌리기 전에 스킬을 정확히 맞춰야 해요.', lv6: '메가 나르의 (R)\'나르!\'를 맞고 벽에 부딪히면 기절하니 벽 근처에서는 싸움을 피하세요. (R)\'단호한 판결\'을 사용해 적을 내려찍으며 입힌 피해만큼 체력을 회복하고 전투를 이어가세요. 나르가 메가 상태일 때는 라인을 당겨서 정글러의 개입을 기다려요.', item: '갈라진 하늘과 판금 장화를 추천해요. 갈라진 하늘은 체력과 공격력을 제공해 전투를 도와줘요. 판금 장화는 나르의 기본 공격 피해를 줄여줘요.', spell: '점멸과 점화를 추천해요. (E)\'폴짝\'으로 거리를 벌리는 나르를 점멸로 따라붙고, 점화로 체력이 낮은 나르를 마무리하세요.' },
    '나서스': { lv1: '나서스는 (Q)\'흡수의 일격\'을 사용하여 미니언 막타를 치며 성장하려 하니 1~2레벨에는 거리를 유지하며 미니언을 함께 챙기세요. 나서스가 (Q)\'흡수의 일격\'을 쓰러 다가올 때 (Q)\'다르킨의 글레이브\'로 두 번 공격하며 체력을 회복하고 압박을 가하세요.', lv3: '나서스의 (W)\'쇠약\'을 맞기 전에 (Q)\'다르킨의 글레이브\'를 사용해 짧게 교환하는 것이 좋아요. (E)\'영혼의 불길\' 장판이 깔리면 그 위에서 싸우지 말고 걸어서 피하며 (W)\'공포의 귀환\'으로 거리를 조절하세요.', lv6: '나서스가 (R)\'사막의 분노\'를 사용하면 체력과 공격 범위가 늘어나고 (Q)\'흡수의 일격\'을 더 자주 사용하니 주의해야 해요. 나서스의 궁극기가 켜진 동안에는 (R)\'단호한 판결\'로 내려찍어 피해를 입히고 체력을 회복하며 버티세요. 라인을 빠르게 밀어 넣어 나서스가 포탑 근처에서 중첩을 쌓지 못하도록 압박하세요.', item: '판금 장화로 나서스의 (Q)\'흡수의 일격\' 같은 기본 공격 피해를 줄이세요. 첫 코어 아이템은 갈라진 하늘을 선택해 전투 중에 체력을 회복하고 추가 피해를 입히는 것이 좋아요.', spell: '점멸과 점화를 추천해요. 나서스는 (P)\'영혼의 포식자\'로 생명력 흡수를 얻으니 점화로 회복을 줄이며 킬각을 잡으세요.' },
    '녹턴': { lv1: '1~2레벨 구간에는 (Q)\'다르킨의 글레이브\'를 활용해 체력을 회복하며 짧게 딜교환을 하세요. 상대가 (P)\'그림자 칼날\' 효과로 체력을 회복하며 버티려 하니 거리 조절에 신경 써야 해요.', lv3: '상대가 (Q)\'황혼의 인도자\'를 맞히고 접근하면 (E)\'찬란한 쇄도\'로 거리를 조절하세요. (E)\'말할 수 없는 공포\'의 연결이 끊어지도록 빠르게 범위를 벗어나 공포를 피하는 것이 중요해요. (W)\'어둠의 장막\'이 사라진 뒤 (Q)\'다르킨의 글레이브\'를 재사용해 상대를 공중에 띄우세요.', lv6: '(R)\'피해망상\'으로 진입하는 타이밍에 맞춰 (R)\'단호한 판결\'을 사용해 받는 피해를 줄이고 체력을 회복하세요. 어둠 속에서는 정글 개입을 확인하기 어려우니 라인을 너무 밀지 말고 관리하세요. 진입 후 상대의 콤보가 끝나면 (W)\'공포의 귀환\'으로 끌어당겨 역공을 가하세요.', item: '판금 장화와 갈라진 하늘을 추천해요. 판금 장화는 (P)\'그림자 칼날\'을 포함한 기본 공격 피해를 줄여주고, 갈라진 하늘은 체력과 공격력을 챙기며 체력을 회복할 수 있게 해줘요.', spell: '점멸과 점화를 추천해요. (P)\'그림자 칼날\'의 회복량을 억제하고 킬각을 잡기 위해 점화가 필요해요.' },
    '다리우스': { lv1: '다리우스는 (P)\'과다출혈\'이 쌓일수록 강해지니 1~2레벨에 길게 싸우지 마세요. (Q)\'학살\'의 도끼날에 맞으면 다리우스가 체력을 회복하니 날 끝을 피하고, (Q)\'다르킨의 글레이브\'로 짧게 교환하며 체력을 회복하세요.', lv3: '다리우스의 (E)\'포획\'에 끌려가면 공중으로 떠오르니 주의하며 (E)\'찬란한 쇄도\'로 거리를 조절하세요. (E)\'포획\'을 피한 뒤에는 (Q)\'다르킨의 글레이브\'를 재사용해 다리우스를 공중에 띄우며 대응하는 것이 좋아요.', lv6: '다리우스의 (R)\'녹서스의 단두대\'는 (P)\'과다출혈\' 중첩이 많을수록 아프니 체력이 낮을 때는 조심하세요. (R)\'단호한 판결\'로 피해를 줄이고 체력을 회복하며 싸우고, 다리우스가 궁극기로 처치하고 초기화하지 못하게 주의하세요.', item: '판금 장화는 다리우스의 기본 공격 피해를 줄여줘요. 갈라진 하늘을 첫 코어로 올려 전투 중 체력을 관리하며 버티세요.', spell: '점멸과 탈진을 추천해요. 다리우스가 (E)\'포획\'으로 끌어당기며 들어올 때 탈진을 써서 피해량을 낮추세요.' },
    '라이즈': { lv1: '라이즈는 (Q)\'과부하\'를 직선으로 발사하여 견제하므로 미니언 뒤에 서서 피해를 최소화하세요. 1~2레벨에는 (Q)\'다르킨의 글레이브\'를 활용해 체력을 회복하며 파밍에 집중하세요. 라이즈가 스킬을 낭비할 때까지 거리를 유지하며 차분하게 대응하세요.', lv3: '라이즈가 (E)\'주문 전이\'를 먼저 맞힌 뒤 (W)\'룬 감옥\'을 사용하면 속박될 수 있으니 주의하세요. 라이즈의 (W)\'룬 감옥\'이 빠진 타이밍에 (E)\'찬란한 쇄도\'로 진입하여 (W)\'공포의 귀환\'으로 끌어당기며 딜교환을 시도하세요. (Q)\'다르킨의 글레이브\'를 재사용하여 라이즈를 공중에 띄우면 연계하기 편해요.', lv6: '라이즈가 (R)\'공간 왜곡\'을 사용해 도망가려 하면 정글러를 불러 함께 압박하세요. 라이즈의 체력이 낮을 때 (R)\'단호한 판결\'로 내려찍으며 (Q)\'다르킨의 글레이브\'와 연계하면 킬을 낼 수 있어요. 라이즈가 궁극기로 다른 곳에 합류하기 전에 라인을 밀어 압박하세요.', item: '첫 코어 아이템으로는 체력과 공격력을 모두 제공하는 갈라진 하늘을 추천해요. 신발은 라이즈의 마법 피해와 군중 제어에 대응하기 위해 헤르메스의 발걸음을 선택하세요.', spell: '점멸과 점화를 추천해요. 라이즈가 스킬로 거리를 벌리기 전에 점화로 체력을 깎고 (R)\'단호한 판결\'로 확실하게 마무리하세요.' },
    '럼블': { lv1: '럼블은 (Q)\'화염방사기\'로 근접 거리에서 강력한 마법 피해를 주며 견제해요. (Q)\'다르킨의 글레이브\'를 활용해 적중 시 체력을 회복하며 버티고, 럼블의 열기가 높아지기 전까지는 거리를 유지하며 미니언을 챙기세요.', lv3: '럼블이 (W)\'고철 방패\'를 켜면 피해가 흡수되니 방패가 사라진 뒤에 (W)\'공포의 귀환\'으로 끌어당기며 싸우세요. (E)\'전기 작살\'에 맞아 마법 저항력이 감소하지 않도록 주의하며, (Q)\'다르킨의 글레이브\'의 재사용 효과로 적을 공중에 띄워 딜교환을 하세요.', lv6: '럼블의 (R)\'이퀄라이저 미사일\' 장판 위에서는 피해가 크니 억지로 버티지 말고 옆으로 피하세요. 럼블이 스킬을 다 쓴 뒤나 과열 상태일 때 (R)\'단호한 판결\'로 내려찍으며 체력을 회복하고 킬각을 노리세요.', item: '첫 코어로 갈라진 하늘을 선택해 전투 지속력을 높이세요. 신발은 럼블의 마법 피해를 견디기 위해 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 점화의 지속 고정 피해로 마무리 피해를 더해 킬을 확정 지으세요.' },
    '레넥톤': { lv1: '레넥톤은 (Q)\'양떼 도륙\'으로 체력을 회복하며 초반에 강하게 압박해요. (Q)\'다르킨의 글레이브\'를 사용해 짧게 공격하고 체력을 회복하며 거리를 조절하세요. 레넥톤의 분노가 높을 때 정면으로 붙으면 피해가 크니 주의하며 막타를 챙기세요.', lv3: '레넥톤이 (E)\'자르고 토막내기\'로 진입해 (W)\'무자비한 포식자\'로 기절시키려 할 때 (W)\'공포의 귀환\'으로 흐름을 끊어주세요. 기절 스킬이 빠진 뒤에 (Q)\'다르킨의 글레이브\' 재사용으로 상대를 공중에 띄워 일방적인 딜교환을 하세요. 분노가 가득 찬 상태의 기절은 보호막까지 파괴하니 최대한 피하는 게 좋아요.', lv6: '레넥톤이 (R)\'강신\'을 사용해 체력을 늘리고 분노를 빠르게 수급할 때는 (R)\'단호한 판결\'의 피해 감소 효과를 활용해 버티세요. (R)\'강신\'의 지속시간이 끝나고 체력이 낮아진 틈을 타 (E)\'찬란한 쇄도\'로 진입해 공격하세요. 정글러가 올 때 (W)\'공포의 귀환\'으로 적을 끌어당겨 호응하면 킬각을 잡기 편해요.', item: '갈라진 하늘을 첫 코어로 선택해 체력과 공격력을 챙기고 교전 중 체력을 회복하세요. 신발은 레넥톤의 기본 공격 피해를 줄여주는 판금 장화가 적절해요.', spell: '점멸과 점화를 추천해요. 점화로 레넥톤의 (Q)\'양떼 도륙\' 회복량을 줄여야 딜교환에서 앞설 수 있어요.' },
    '렝가': { lv1: '수풀 근처에 서지 말고 거리 조절을 하며 (Q)\'다르킨의 글레이브\'로 체력을 회복하고 견제하세요. 렝가가 (P)\'보이지 않는 포식자\'로 도약해 들어올 때 빠르게 반응해 뒤로 물러나야 해요. 첫 웨이브는 빠르게 밀어내어 상대가 수풀을 활용하지 못하게 하세요.', lv3: '(E)\'올가미 투척\'에 속박당하지 않도록 무빙에 신경 쓰고 (E)\'찬란한 쇄도\'로 빠르게 거리를 좁히거나 피하세요. 렝가가 진입하면 (W)\'공포의 귀환\'으로 끌어당겨 흐름을 끊고 (Q)\'다르킨의 글레이브\' 재사용으로 공중에 띄워 딜교환을 마무리하세요. 상대의 (W)\'전투의 포효\'가 빠진 시점을 노려 공격하는 것이 좋아요.', lv6: '(R)\'사냥의 전율\'을 켜고 위장 상태로 접근하는 렝가의 진입 타이밍에 맞춰 (R)\'단호한 판결\'을 사용해 피해를 줄이고 체력을 회복하세요. 렝가가 도약한 직후 (W)\'공포의 귀환\'으로 끌어당기면 정글러의 개입을 받기 편해요. 라인을 당겨서 유지하며 상대가 수풀을 통해 기습할 공간을 없애세요.', item: '판금 장화와 갈라진 하늘을 가세요. 판금 장화는 렝가의 기본 공격 피해를 줄여주고 갈라진 하늘은 체력과 공격력을 동시에 보충해줘요.', spell: '점멸과 점화를 추천해요. 점화는 렝가의 (W)\'전투의 포효\'로 인한 체력 회복을 억제하고 마무리 피해를 입히기에 좋아요.' },
    '리븐': { lv1: '리븐은 (Q)\'부러진 날개\'로 빠르게 접근해 (P)\'룬 검\' 강화 평타로 강한 압박을 해요. 리븐이 들어올 때 (Q)\'다르킨의 글레이브\'로 체력을 회복하며 버티고, 상대의 스킬 쿨타임이 돌 때까지 거리를 유지하세요. 무리하게 쫓기보다 체력 관리를 하며 결심 중첩을 쌓는 것이 중요해요.', lv3: '리븐의 (W)\'기 폭발\' 기절에 맞으면 연계 공격을 다 맞으니, 이 스킬이 빠진 뒤에 (E)\'찬란한 쇄도\'로 진입해 딜교환을 하세요. 리븐이 (Q)\'부러진 날개\' 세 번째 타격으로 밀쳐내려 할 때 (W)\'공포의 귀환\'으로 끌어당겨 흐름을 끊어주세요. 상대의 (E)\'용맹\' 보호막이 사라지는 타이밍에 맞춰 공격을 쏟아부으세요.', lv6: '리븐이 (R)\'추방자의 검\'을 켜면 사거리와 공격력이 늘어나니, 체력이 낮은 상태에서 원거리 공격에 맞지 않게 조심하세요. 리븐의 진입 타이밍에 (R)\'단호한 판결\'을 사용해 피해를 줄이고 체력을 회복하며 버티는 것이 좋아요. 라인을 밀어 넣고 정글러를 부른 뒤, (Q)\'다르킨의 글레이브\' 재사용으로 띄우며 킬각을 잡으세요.', item: '판금 장화와 갈라진 하늘을 추천해요. 판금 장화로 리븐의 (P)\'룬 검\' 평타 피해를 줄이고, 갈라진 하늘의 체력과 공격력으로 지속 교전에서 앞서나가세요.', spell: '점멸과 순간이동을 추천해요. 리븐의 기동력이 좋으므로 순간이동으로 라인 복귀와 합류를 빠르게 하는 것이 중요해요.' },
    '리산드라': { lv1: '리산드라는 (Q)\'얼음 파편\'이 미니언을 꿰뚫어 둔화를 걸고 견제하니 미니언 뒤에 숨어도 맞아요. (Q)\'다르킨의 글레이브\'로 체력을 회복하며 견제를 버티고, 상대가 평타를 치러 다가올 때 짧게 딜교환을 하세요. 1~2레벨에는 무리하게 진입하기보다 (P)\'전쟁 단련\' 중첩을 쌓는 데 집중하세요.', lv3: '(W)\'서릿발\'에 묶여도 스킬 사용은 가능하니 당황하지 말고 (W)\'공포의 귀환\'으로 리산드라를 끌어당겨 거리를 좁히세요. 리산드라가 (E)\'얼음갈퀴 길\'로 진입한다면 (E)\'찬란한 쇄도\'로 빠르게 접근해 (Q)\'다르킨의 글레이브\' 재사용으로 공중에 띄우세요. 상대의 속박 스킬이 빠진 타이밍을 노려 강하게 압박하세요.', lv6: '(R)\'얼음 무덤\'으로 기절당하면 스킬을 쓸 수 없으니, 상대가 궁극기를 쓰기 전에 (R)\'단호한 판결\'로 먼저 진입해 피해를 입히고 체력을 회복하세요. 리산드라가 자신에게 (R)\'얼음 무덤\'을 써서 무적 상태가 되면 공격을 멈추고 무적이 끝나는 시점을 기다리세요. 정글러가 합류했을 때 (W)\'공포의 귀환\'으로 리산드라를 끌어당겨 집중 공격하세요.', item: '맬모셔스의 아귀를 가서 마법 저항력과 생명선 보호막으로 리산드라의 폭발적인 피해를 버티세요. 신발은 (W)\'서릿발\'의 속박과 (R)\'얼음 무덤\'의 기절 시간을 줄여주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 정화를 추천해요. (W)\'서릿발\'의 속박이나 (R)\'얼음 무덤\'의 기절을 정화로 즉시 풀고 (R)\'단호한 판결\'로 역공할 수 있어요.' },
    '마스터이': { lv1: '마스터 이는 (P)\'2연속 공격\'으로 지속적인 평타 피해를 입혀요. 1~2레벨에는 (Q)\'다르킨의 글레이브\'를 사용하여 적절히 체력을 회복하며 거리를 조절하세요. (Q)\'일격 필살\'을 사용해 들어오는 순간에는 평타로 맞대응하기보다 거리를 두는 것이 좋아요.', lv3: '마스터 이가 (W)\'명상\'을 사용해 피해를 줄이며 회복하려 하면 (W)\'공포의 귀환\'으로 끌어당겨 딜교환을 시도하세요. (Q)\'일격 필살\' 사용 시에는 대상을 지정할 수 없으니 스킬을 아껴 두었다가 착지한 뒤에 (Q)\'다르킨의 글레이브\'의 에어본을 노려야 해요. (E)\'우주류 검술\'이 켜진 상태에서 평타를 계속 맞으면 위험하니 주의하세요.', lv6: '마스터 이가 (R)\'최후의 전사\'를 켜면 이동 속도와 공격 속도가 빨라지니 (R)\'단호한 판결\'로 내려찍어 체력을 회복하며 버티세요. (R)\'최후의 전사\' 상태의 마스터 이는 둔화 효과에 면역이므로 주의가 필요해요. 마스터 이가 킬을 먹고 스킬 쿨타임이 줄어들지 않도록 라인을 밀어두고 정글러와 함께 압박하세요.', item: '첫 코어로 갈라진 하늘을 선택해 체력과 공격력을 함께 챙기세요. 신발은 마스터 이의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 마스터 이가 (W)\'명상\'으로 체력을 회복할 때 점화로 회복량을 줄여야 해요.' },
    '마오카이': { lv1: '마오카이는 (Q)\'덤불 주먹\'으로 뒤로 밀어내고 둔화를 걸며 (P)\'마법 흡수\'를 통해 체력을 회복해요. 1~2레벨에는 마오카이가 막타를 치려 다가올 때 (Q)\'다르킨의 글레이브\'를 사용하여 체력을 회복하며 맞서세요. (Q)\'덤불 주먹\'의 충격파를 피하며 거리를 조절해야 해요.', lv3: '마오카이가 (W)\'뒤틀린 전진\'으로 돌진할 때는 대상을 지정할 수 없으니 (W)\'공포의 귀환\'을 아껴두세요. 속박이 풀린 직후 (W)\'공포의 귀환\'으로 마오카이를 끌어당기고 (Q)\'다르킨의 글레이브\'를 재사용해 공중에 띄우세요. 수풀에 깔린 (E)\'묘목 던지기\'에 닿지 않도록 조심하세요.', lv6: '마오카이의 (R)\'대자연의 마수\'는 벽이 전진하며 속박하니 벽의 경로를 보고 옆으로 비켜서세요. (R)\'단호한 판결\'로 적을 내려찍어 체력을 회복하며 전투를 이어가세요. 마오카이가 (W)\'뒤틀린 전진\'으로 들어오면 (E)\'찬란한 쇄도\'로 위치를 잡는 것이 좋아요.', item: '갈라진 하늘을 첫 코어로 가서 전투 지속력을 높이세요. 신발은 마법 저항력과 강인함을 제공하는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 점화를 사용하여 마오카이의 체력 회복 효과를 감소시키며 킬각을 잡으세요.' },
    '말자하': { lv1: '말자하는 (P)\'공허 태세\'가 켜져 있으면 피해를 덜 받고 군중 제어에 면역이니, (Q)\'다르킨의 글레이브\'로 먼저 공격해서 이 효과를 벗겨야 해요. (Q)\'공허의 부름\' 투사체에 맞으면 침묵 상태가 되어 스킬을 못 쓰니 문이 열리는 위치를 피해 이동하세요. (Q)\'공허의 부름\'이 빠진 틈에 평타를 섞어 꾸준히 압박하세요.', lv3: '(E)\'재앙의 환상\'에 걸리면 지속 피해를 입고 (W)\'공허의 무리\'가 몰려오니, 환상에 걸린 상태로 길게 싸우지 말고 빠르게 빠지세요. (E)\'찬란한 쇄도\'로 진입할 때 말자하를 가르기 범위 가장자리에 두어 마법 피해까지 함께 입히는 것이 중요해요. (W)\'공포의 귀환\'으로 끌어당긴 후 (Q)\'다르킨의 글레이브\'를 재사용해 공중에 띄우면 짧은 시간 동안 확실한 피해를 줄 수 있어요.', lv6: '(R)\'황천의 손아귀\'는 제압이라 정화로 풀 수 없으니, 상대의 궁극기가 빠진 것을 확인한 뒤에 진입하세요. (R)\'단호한 판결\'을 사용할 때 받는 피해량이 감소하므로 이를 활용해 말자하의 견제를 버티며 내려찍어 체력을 회복하세요. 말자하가 라인을 빠르게 밀어 포탑 근처에 있을 때는 (W)\'공포의 귀환\'으로 끌어당겨 킬각을 노리세요.', item: '갈라진 하늘로 체력과 공격력을 챙겨 말자하의 견제를 버티고 체력을 회복하세요. 신발은 마법 저항력을 높이고 (Q)\'공허의 부름\'의 침묵 지속시간을 줄여주는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 점화를 추천해요. (R)\'황천의 손아귀\' 제압은 정화로 풀 수 없으니, 정화보다는 점화로 피해를 더 입히는 것이 효과적이에요.' },
    '말파이트': { lv1: '말파이트는 (Q)\'지진의 파편\'으로 견제하는데, 대상 지정 스킬이라 미니언 뒤에 숨어도 피할 수 없어요. (P)\'화강암 방패\'가 있을 때는 평타 교환이 손해니 (Q)\'다르킨의 글레이브\'로 짧게 치고 빠지며 체력을 회복하세요. 방패가 사라진 틈을 타서 평타를 섞어 (P)\'전쟁 단련\' 중첩을 쌓으세요.', lv3: '(E)\'지면 강타\'를 맞으면 공격 속도가 낮아지니, 말파이트가 스킬을 쓴 뒤에 (W)\'공포의 귀환\'으로 끌어당겨 교전을 시작하세요. (W)\'천둥소리\'의 여진 피해를 조심하며 (E)\'찬란한 쇄도\'의 가장자리 마법 피해로 말파이트의 높은 방어력을 공략하세요. (Q)\'다르킨의 글레이브\'의 재사용 효과로 공중에 띄우면 상대의 추격을 따돌리기 편해요.', lv6: '(R)\'멈출 수 없는 힘\'은 저지 불가 돌진이라 (W)\'공포의 귀환\' 같은 스킬로 끊을 수 없고, 맞으면 공중에 떠서 스킬을 쓸 수 없어요. 말파이트가 궁극기를 쓴 직후에 (R)\'단호한 판결\'로 내려찍어 피해를 입히고 체력을 회복하며 버티세요. 라인을 밀 때는 정글러의 개입을 고려해 (R)\'멈출 수 없는 힘\'의 사거리 밖에서 거리 조절을 하세요.', item: '칠흑의 양날 도끼를 첫 코어로 선택해 말파이트의 높은 방어력을 깎고 체력을 보충하세요. 신발은 마법 저항력을 높이고 (Q)\'지진의 파편\' 둔화 등의 지속시간을 줄여주는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 순간이동을 추천해요. 말파이트의 (R)\'멈출 수 없는 힘\' 각을 피하고 빠른 합류로 팀에 기여하는 것이 중요해요.' },
    '모데카이저': { lv1: '모데카이저의 (Q)\'말살\'은 해당 지역의 모든 적에게 들어가니 미니언 뒤에 숨어도 소용없고, 범위 밖으로 비켜서야 해요. (Q)\'다르킨의 글레이브\'로 짧게 공격하고 빠르게 빠지면서 (P)\'암흑 탄생\' 오라가 켜지지 않게 조심하세요. 첫 웨이브는 무리하게 붙지 말고 기본 공격으로 결심 중첩을 쌓는 데 집중하세요.', lv3: '(E)\'죽음의 손아귀\'에 끌려가면 (Q)\'말살\' 연계에 큰 피해를 입으니 거리 조절을 하며 상대 스킬을 유도하세요. 모데카이저가 보호막을 켜는 (W)\'불멸\'을 사용한 뒤에 (W)\'공포의 귀환\'으로 끌어당겨 딜교환을 시작하는 것이 효율적이에요. (E)\'찬란한 쇄도\'를 사용할 때는 가장자리 피해를 입히며 빠르게 진입하고 빠지세요.', lv6: '(R)\'죽음의 세계\'에 끌려가면 정화나 순간이동으로도 빠져나올 수 없으니, 끌려가기 전에 (R)\'단호한 판결\'로 피해를 주고 체력을 회복해 생존력을 높이세요. 모데카이저가 궁극기를 쓰기 전에 (Q)\'다르킨의 글레이브\' 재사용으로 띄워 공격 흐름을 끊는 것이 중요해요. 라인을 밀어두고 정글러를 부르면 모데카이저가 궁극기로 격리시키기 전까지는 함께 싸우기 편해요.', item: '헤르메스의 발걸음과 갈라진 하늘을 추천해요. 마법 저항력으로 피해를 줄이고 체력과 회복력을 얻어 모데카이저와의 지속 싸움에서 버티기 좋아요.', spell: '점멸과 점화를 추천해요. (W)\'불멸\'을 통해 회복하는 체력을 점화의 치유 감소 효과로 억제해야 킬각을 잡기 편해요.' },
    '문도박사': { lv1: '문도 박사는 (Q)\'오염된 뼈톱\'으로 체력 비례 피해를 주고 둔화를 걸어요. 이 스킬은 처음 맞는 적에게만 적중하므로 미니언 뒤에 서서 막아내세요. (Q)\'다르킨의 글레이브\'로 짧게 공격하며 체력을 회복하고 통을 주우러 오는 타이밍을 노려 견제하세요.', lv3: '(W)\'심장 전기 충격\'이 켜진 동안은 피해를 저장해 회복하므로 무리하게 붙어 싸우지 마세요. (E)\'찬란한 쇄도\'를 사용할 때 문도 박사를 범위 가장자리에 맞혀 최대 체력 비례 피해를 입히세요. (W)\'공포의 귀환\'으로 끌어당긴 뒤 평타와 스킬을 섞어 짧게 딜교환을 하세요.', lv6: '(R)\'최대 투여량\'을 쓴 문도 박사는 회복력이 매우 강해지므로 궁극기가 빠진 뒤에 (R)\'단호한 판결\'로 내려찍으세요. (P)\'가고 싶은 데로 간다\'는 처음 맞는 이동 불가 효과에만 저항하고 재사용 대기시간도 있으니, 끌어당기기와 띄우기까지 막는다고 생각하지 마세요. 정글러가 올 때 (W)\'공포의 귀환\'으로 끌어당겨 확실하게 처치하세요.', item: '몰락한 왕의 검을 첫 코어로 선택해 체력이 높은 문도 박사를 효율적으로 공격하고 생명력 흡수를 챙기세요. 신발은 (E)\'둔기에 의한 외상\'과 기본 공격의 물리 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 문도 박사는 회복 수단이 매우 많으므로 점화의 치유 감소 효과가 킬각을 잡는 데 필수적이에요.' },
    '바루스': { lv1: '바루스는 (Q)\'꿰뚫는 화살\'을 충전해 원거리에서 강하게 견제해요. 충전 중에는 바루스의 이동 속도가 느려지니, 이때 (E)\'찬란한 쇄도\'로 빠르게 접근해 평타와 (Q)\'다르킨의 글레이브\'로 체력을 회복하며 압박하세요. 정면에서 걷기보다 옆으로 움직이며 화살을 피하는 것이 중요해요.', lv3: '(W)\'역병 화살\'의 중첩이 쌓인 상태에서 (E)\'퍼붓는 화살\'이나 (Q)\'꿰뚫는 화살\'을 맞으면 최대 체력 비례 피해가 들어와 아파요. 바루스가 (E)\'퍼붓는 화살\'을 사용해 둔화를 걸었다면, 즉시 (W)\'공포의 귀환\'으로 끌어당겨 거리를 좁히세요. 이후 (Q)\'다르킨의 글레이브\'를 재사용해 바루스를 공중에 띄우면 일방적인 딜교환이 가능해요.', lv6: '(R)\'부패의 사슬\'에 맞으면 속박되어 일방적으로 공격받으니, 투사체가 날아오는 경로에서 빠르게 벗어나세요. 바루스가 궁극기를 빗맞혔을 때 (R)\'단호한 판결\'로 진입하면, 날아오르는 동안 받는 피해가 감소해 안전하게 붙을 수 있어요. 이후 (W)\'공포의 귀환\'과 평타 콤보로 빠르게 처리하세요.', item: '판금 장화와 갈라진 하늘을 추천해요. 판금 장화로 바루스의 기본 공격 피해를 줄이고, 갈라진 하늘의 체력과 공격력 그리고 첫 타격 회복 효과로 유지력을 높이세요.', spell: '점멸과 유체화를 추천해요. 유체화의 이동 속도 증가 효과가 원거리에서 견제하는 바루스에게 접근하는 데 큰 도움을 줘요.' },
    '베인': { lv1: '베인은 (W)\'은화살\'로 최대 체력 비례 고정 피해를 입히고 (Q)\'구르기\'로 거리를 조절해요. (Q)\'다르킨의 글레이브\'의 회복 효과를 활용해 견제를 버티며 (P)\'전쟁 단련\' 중첩을 쌓으세요. 베인이 막타를 치러 올 때 짧게 딜교환을 하고 빠르게 빠지세요.', lv3: '(E)\'선고\'에 맞으면 뒤로 밀려나니 벽 근처에 서지 말고 (E)\'찬란한 쇄도\'로 빠르게 접근하세요. 베인이 (Q)\'구르기\'로 빠지기 전에 (W)\'공포의 귀환\'으로 끌어당겨 딜교환을 이어가세요. (Q)\'다르킨의 글레이브\' 재사용으로 베인을 공중에 띄워 공격을 마무리하세요.', lv6: '(R)\'결전의 시간\'이 켜진 베인은 (Q)\'구르기\'를 쓸 때마다 투명해져서 접근하기 까다로워요. 베인이 투명해지기 전에 (R)\'단호한 판결\'로 덮쳐 피해 감소 효과로 버티며 체력을 회복하세요. 투명 상태일 때는 무리하게 쫓지 말고 미니언을 밀어 넣어 베인을 압박하세요.', item: '판금 장화와 갈라진 하늘을 추천해요. 판금 장화는 기본 공격 피해를 줄여주고, 갈라진 하늘은 높은 체력과 체력 회복으로 유지력을 도와줘요.', spell: '점멸과 순간이동을 추천해요. (Q)\'구르기\'로 거리를 벌리는 베인을 쫓기 위해 점멸이 필요하며 라인 관리를 위해 순간이동을 사용하세요.' },
    '볼리베어': { lv1: '볼리베어는 (Q)\'번개 강타\'를 활용해 빠르게 접근하며 기절을 시킬 수 있어요. 1~2레벨에는 무리하게 붙지 말고 (Q)\'다르킨의 글레이브\'로 체력을 회복하며 거리를 유지하세요. 볼리베어의 (P)\'무자비한 폭풍\'이 쌓이기 전에 거리를 벌리는 것이 중요해요.', lv3: '볼리베어가 (W)\'광란의 상처\'로 표식을 남기고 다시 사용해 체력을 회복하는 것을 조심하세요. (E)\'찬란한 쇄도\'를 사용해 볼리베어의 (E)\'천공 분열\' 범위 밖으로 빠르게 이동하거나 (W)\'공포의 귀환\'으로 적을 끌어당겨 딜교환을 시도하세요. 볼리베어의 (Q)\'번개 강타\'가 빠진 타이밍에 (Q)\'다르킨의 글레이브\'의 에어본을 활용해 압박하세요.', lv6: '볼리베어는 (R)\'폭풍을 부르는 자\'로 포탑을 무력화하며 다이브할 수 있으니 체력이 낮을 때 포탑 밑에 있는 것은 위험해요. 볼리베어가 궁극기를 사용해 체력을 얻었다면 (R)\'단호한 판결\'로 맞대응하며 회복력을 활용하세요. 라인 관리 시 볼리베어의 궁극기 범위에 걸리지 않도록 주의하며 정글러의 위치를 확인하세요.', item: '첫 코어로 갈라진 하늘을 선택해 전투 지속력을 높이세요. 신발은 볼리베어의 (E)\'천공 분열\' 둔화와 (Q)\'번개 강타\' 기절을 줄이기 위해 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 점화로 볼리베어의 (W)\'광란의 상처\'를 통한 체력 회복을 억제하며 킬각을 잡으세요.' },
    '블라디미르': { lv1: '블라디미르는 (Q)\'수혈\'로 체력을 흡수하며 견제하는데, 대상 지정 스킬이라 미니언 뒤에 숨거나 걸어서 피할 수 없어요. (Q)\'다르킨의 글레이브\'로 체력을 회복하며 짧게 딜교환을 하고 버티는 것이 좋아요. 초반에는 무리하기보다 (Q)\'다르킨의 글레이브\'의 회복력을 활용해 체력을 관리하세요.', lv3: '블라디미르의 (E)\'선혈의 파도\'는 적 유닛이 파도를 가로막을 수 있으니 미니언 뒤에 위치해서 피해를 줄이세요. 블라디미르가 (W)\'피의 웅덩이\'로 대상으로 지정할 수 없게 되는 동안은 공격을 아끼고, 웅덩이가 끝난 직후 (E)\'찬란한 쇄도\'로 거리를 좁히며 딜교환을 시작하세요.', lv6: '블라디미르가 (R)\'혈사병\'을 사용하면 받는 피해가 커지므로 감염된 상태에서는 교전을 멈추고 거리를 두어야 해요. 블라디미르가 (W)\'피의 웅덩이\'로 대상 지정이 안 되는 동안은 기다렸다가, 웅덩이가 끝난 직후 (R)\'단호한 판결\'로 내려찍어 피해를 입히고 체력을 회복하세요. 상대가 강해지는 구간이므로 라인을 빠르게 밀어 정글러의 개입에 대비하는 것이 좋아요.', item: '마법 피해를 줄이기 위해 헤르메스의 발걸음을 먼저 올리고 갈라진 하늘을 첫 코어 아이템으로 선택하세요. 전투 중 체력 회복을 통해 블라디미르의 유지력에 맞설 수 있어요.', spell: '점멸과 점화를 추천해요. 블라디미르는 (Q)\'수혈\'을 통해 체력을 회복하므로 점화로 회복 효과를 억제해야 해요.' },
    '뽀삐': { lv1: '뽀삐가 (Q)\'망치 강타\'로 만드는 둔화 지대를 조심하며 거리 조절을 하세요. (Q)\'다르킨의 글레이브\'를 활용해 짧게 교환하며 체력을 회복하고 (P)\'전쟁 단련\' 중첩을 쌓으세요. 뽀삐가 방패를 주워 (P)\'강철의 외교관\' 보호막을 얻기 전에 먼저 접근하세요.', lv3: '뽀삐가 (W)\'굳건한 태세\'를 사용하면 (E)\'찬란한 쇄도\' 같은 돌진이 막히니 주의하세요. 뽀삐의 (E)\'용감한 돌진\'에 밀려 벽에 부딪히지 않도록 라인 중앙에서 싸우는 것이 좋아요. 뽀삐의 (W)\'굳건한 태세\'가 빠진 뒤에 (W)\'공포의 귀환\'으로 끌어당기며 싸움을 거세요.', lv6: '뽀삐의 (R)\'수호자의 심판\'을 맞으면 멀리 날아가 흐름이 끊기니 조심하세요. 뽀삐의 (W)\'굳건한 태세\'가 빠진 상태에서 (R)\'단호한 판결\'로 내려찍으면 높은 피해와 회복을 챙길 수 있어요. 뽀삐가 궁극기를 사용해 멀리 날아간 뒤에는 라인을 빠르게 밀어 압박하세요.', item: '첫 코어로 갈라진 하늘을 선택해 전투 지속력을 높이세요. 신발은 뽀삐의 물리 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 초반 교전에서 뽀삐에게 더 큰 피해를 입히며 킬각을 잡으세요.' },
    '사이온': { lv1: '사이온의 (E)\'학살자의 포효\'는 미니언을 밀어내며 관통하니 미니언 뒤에 숨지 말고 비스듬히 서서 피하세요. 상대가 (Q)\'대량 학살 강타\'를 충전할 때 범위 밖으로 벗어난 뒤 (Q)\'다르킨의 글레이브\'로 짧게 딜교환하고 체력을 회복하세요. 첫 웨이브부터 결심 중첩을 쌓으며 거리를 유지하는 것이 중요해요.', lv3: '(W)\'영혼의 용광로\' 보호막이 켜져 있을 때는 딜교환을 자제하고 보호막이 폭발한 뒤에 진입하세요. (E)\'찬란한 쇄도\'로 빠르게 접근해 (W)\'공포의 귀환\'으로 사이온을 끌어당겨 딜교환을 시작하세요. 사이온이 (Q)\'대량 학살 강타\'를 사용해 띄우려 하면 빠르게 옆으로 움직여 피한 뒤 공격하세요.', lv6: '(R)\'멈출 수 없는 맹공\'은 저지 불가 상태로 돌진하니 일직선상에서 벗어나 옆으로 피하세요. 사이온이 돌진을 멈춘 순간 (R)\'단호한 판결\'로 내려찍어 큰 피해를 주고 체력을 회복하세요. 적이 쓰러져도 (P)\'영광스러운 죽음\'으로 공격해 오니 완전히 소멸할 때까지 거리를 벌리세요.', item: '칠흑의 양날 도끼를 첫 코어로 가서 방어력을 깎고 체력을 보충하세요. 신발은 (Q)\'대량 학살 강타\'의 기절과 (E)\'학살자의 포효\'의 둔화 지속시간을 줄여주는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 순간이동을 추천해요. 사이온의 강한 라인 푸시력에 대응해 빠르게 복귀하고 손실을 줄여야 해요.' },
    '사일러스': { lv1: '사일러스는 (Q)\'사슬 후려치기\'로 둔화를 걸고 (P)\'페트리사이트 폭발\'로 평타 피해를 더해요. (Q)\'다르킨의 글레이브\'로 체력을 회복하며 버티고, 사슬이 교차해 터지는 지점을 피하세요. 상대의 평타 강화 충전이 없을 때 짧게 딜교환을 하세요.', lv3: '(W)\'국왕시해자\'의 회복량이 많으므로 체력이 낮을 때 진입하는 사일러스를 주의하세요. (E)\'도주 / 억압\'의 두 번째 돌진에 맞지 않게 옆으로 움직인 뒤 (W)\'공포의 귀환\'으로 끌어당기세요. (E)\'찬란한 쇄도\'를 사용해 빠르게 접근하여 (Q)\'다르킨의 글레이브\' 재사용 효과로 공중에 띄우세요.', lv6: '사일러스가 (R)\'강탈\'로 내 (R)\'단호한 판결\'을 훔쳐 사용하며 진입하고 체력을 회복해요. 사일러스가 훔친 궁극기로 내려찍은 직후 (W)\'공포의 귀환\'으로 끌어당겨 반격하세요. (R)\'단호한 판결\'의 피해 감소 효과를 활용해 상대의 폭발적인 피해를 받아내며 싸우세요.', item: '맬모셔스의 아귀를 첫 코어로 가서 마법 저항력을 높이고 생명선 보호막으로 생존력을 챙기세요. 신발은 강인함으로 (Q)\'사슬 후려치기\'의 둔화 지속시간을 줄여주는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 점화를 추천해요. (W)\'국왕시해자\'의 강력한 체력 회복을 점화의 치유 감소 효과로 억제하세요.' },
    '세주아니': { lv1: '(Q)\'혹한의 맹습\'에 맞으면 공중에 띄워져 스킬을 쓸 수 없으니 거리 조절을 잘 하세요. (Q)\'다르킨의 글레이브\'를 사용해 적을 견제하면서 체력을 회복하며 파밍해요. 상대가 (W)\'혹한의 서릿발\'로 미니언을 밀어내며 접근할 때 주의하세요.', lv3: '(W)\'혹한의 서릿발\'로 서리 중첩이 쌓이기 전에 (Q)\'다르킨의 글레이브\'의 재사용 효과로 적을 공중에 띄워 흐름을 끊어주세요. 상대의 (Q)\'혹한의 맹습\'이 빠진 것을 확인하고 (W)\'공포의 귀환\'으로 끌어당겨 딜교환을 시도하세요. (E)\'찬란한 쇄도\'로 진입할 때는 상대의 기절 스킬 범위를 피하며 빠르게 공격해요.', lv6: '(R)\'빙하 감옥\'에 적중당하면 기절하여 대응하기 어려우니 상대의 궁극기 모션을 잘 살펴주세요. (R)\'단호한 판결\'을 사용하여 진입하며 피해량을 줄이고, 적에게 입힌 피해로 체력을 회복하며 전투를 유지하세요. 아군 정글러가 합류하면 (W)\'공포의 귀환\'으로 세주아니를 끌어당겨 호응하세요.', item: '헤르메스의 발걸음과 갈라진 하늘을 선택해요. 헤르메스의 발걸음은 (E)\'만년 서리\'와 (R)\'빙하 감옥\'의 기절 지속시간을 줄여줘요. 갈라진 하늘은 체력을 높여주고 공격 시 체력을 회복해 지속 싸움에 도움을 줘요.', spell: '점멸과 정화를 추천해요. 세주아니의 (E)\'만년 서리\'나 (R)\'빙하 감옥\'에 의한 기절 효과를 정화로 빠르게 풀고 반격하세요.' },
    '세트': { lv1: '세트는 (Q)\'주먹다짐\'을 사용해 이동 속도를 높이며 다가와 강력한 평타를 날려요. (Q)\'다르킨의 글레이브\'로 짧게 맞받아 체력을 회복하며 세트의 접근 타이밍을 보세요. 1~2레벨 구간에서는 무리하게 맞붙기보다 (Q)\'다르킨의 글레이브\'의 회복을 활용하며 견제해요.', lv3: '세트의 (E)\'안면 강타\'는 양옆의 적을 끌어당겨 기절시키니 미니언 사이에 서지 않도록 주의하세요. 세트가 피해를 입어 (W)\'강펀치\' 보호막이 두꺼워졌을 때는 (E)\'찬란한 쇄도\'로 들어가지 마세요. 세트의 (E)\'안면 강타\'가 빠진 것을 확인한 뒤 (W)\'공포의 귀환\'으로 끌어당기고 (Q)\'다르킨의 글레이브\'를 재사용해 에어본을 맞히세요.', lv6: '세트의 (R)\'대미 장식\'은 적을 붙잡아 제압한 뒤 내리꽂으니 사용될 때 근처에 서 있지 마세요. 세트의 (R)\'대미 장식\'이 빠진 뒤 (R)\'단호한 판결\'로 내려찍어 체력을 회복하며 대응하세요. 세트가 체력이 낮아 (P)\'투기장의 투지\'로 회복하기 전에 (R)\'단호한 판결\'을 맞춰 승부를 보세요.', item: '첫 코어 아이템으로 갈라진 하늘을 구매해 전투 지속력을 높이세요. 신발은 세트의 기본 공격 피해를 줄여주는 판금 장화가 적절해요.', spell: '점멸과 점화를 추천해요. 점화로 세트가 (P)\'투기장의 투지\'를 사용하여 체력을 회복하는 것을 억제하세요.' },
    '쉔': { lv1: '쉔은 (Q)\'황혼 강습\'으로 대상 최대 체력 비례 피해를 주고 둔화를 걸며 스킬을 쓸 때마다 (P)\'기 보호막\'을 얻어요. 1~2레벨에는 쉔이 (P)\'기 보호막\'을 두르고 있을 때 무리하게 교환하지 말고 (Q)\'다르킨의 글레이브\'로 체력을 회복하며 버티세요. 쉔의 (Q)\'황혼 강습\'이 지나가는 경로를 주의하며 거리를 조절해야 해요.', lv3: '쉔이 (E)\'그림자 돌진\'으로 도발을 사용하면 도발 중에는 스킬을 쓸 수 없으니 주의하세요. 쉔이 (W)\'의지의 결계\'를 펼치면 기본 공격이 차단되므로 결계가 사라진 뒤에 (W)\'공포의 귀환\'으로 끌어당겨 교환하세요. (E)\'찬란한 쇄도\'를 사용하여 쉔의 도발 범위를 벗어나거나 거리를 좁히는 플레이가 필요해요.', lv6: '쉔이 (R)\'단결된 의지\'로 다른 라인에 합류하려 하면 빠르게 라인을 밀어 압박하세요. 쉔이 복귀하기 전 (R)\'단호한 판결\'로 내려찍어 피해를 입히고 체력을 회복하며 킬각을 잡으세요. (E)\'그림자 돌진\' 도발에 걸리면 스킬을 쓸 수 없으니, (W)\'공포의 귀환\'은 돌진이 빠진 것을 확인한 뒤에 쓰세요.', item: '첫 코어로 갈라진 하늘을 선택해 전투 지속력을 높이세요. 신발은 (E)\'그림자 돌진\'의 도발 지속 시간을 줄여주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 쉔이 (R)\'단결된 의지\'를 사용해 도망가려 할 때 점화를 사용하여 마무리 피해를 입히세요.' },
    '쉬바나': { lv1: '1~2레벨에는 쉬바나의 (Q)\'잉걸불 일격\' 사거리를 의식하며 짧은 딜교환을 시도해요. (Q)\'다르킨의 글레이브\'를 사용하여 피해를 입히고 체력을 회복하며 체력 관리를 하세요. (E)\'용암 분출\'의 둔화에 맞지 않도록 무빙에 신경 써야 해요.', lv3: '(W)\'지옥불 방패\'의 보호막이 사라진 타이밍에 (W)\'공포의 귀환\'으로 끌어당겨 딜교환을 시작해요. 이후 (Q)\'다르킨의 글레이브\'를 재사용해 공중에 띄워 상대의 움직임을 일시적으로 제한하세요. (E)\'찬란한 쇄도\'의 가장자리 피해를 입히며 적절한 거리를 유지하는 것이 좋아요.', lv6: '쉬바나가 (R)\'용의 강림\'으로 진입하며 공포를 걸 때 (R)\'단호한 판결\'을 사용하여 피해를 줄이고 체력을 회복해요. 용 형상일 때의 (Q)\'잉걸불 일격\' 고정 피해가 매우 강력하므로 정면 승부는 피하세요. 라인을 먼저 밀어넣고 정글러와 함께 압박하는 구도를 만드세요.', item: '헤르메스의 발걸음과 맬모셔스의 아귀를 추천해요. (E)\'용암 분출\'의 둔화와 (R)\'용의 강림\'의 공포 지속시간을 줄이고 마법 피해를 막아낼 보호막이 필요해요.', spell: '점멸과 순간이동을 추천해요. 순간이동으로 라인 복귀 시간을 줄이고 점멸로 (W)\'공포의 귀환\'을 맞힐 각을 만드세요.' },
    '스웨인': { lv1: '스웨인은 (Q)\'죽음의 손길\'로 견제하며 (P)\'굶주린 새떼\'로 체력을 회복해요. (Q)\'다르킨의 글레이브\'를 활용해 함께 체력을 회복하며 (P)\'전쟁 단련\' 중첩을 쌓는 데 집중하세요. 초반에는 무리하게 붙기보다 짧은 딜교환으로 체력 손실을 최소화하는 것이 좋아요.', lv3: '(E)\'속박명령\'의 파동이 돌아올 때 옆으로 피하는 것이 중요해요. 파동을 피한 뒤 (W)\'공포의 귀환\'으로 스웨인을 끌어당기고 (Q)\'다르킨의 글레이브\'의 재사용 효과로 공중에 띄워 공격하세요. (W)\'제국의 눈\'의 둔화에 걸리면 (E)\'찬란한 쇄도\'로 빠르게 거리를 좁히거나 빠져나가세요.', lv6: '(R)\'악의 승천\'을 켠 스웨인은 주변 적의 체력을 흡수하니 너무 오래 붙어 있지 마세요. (R)\'단호한 판결\'을 사용해 피해를 줄이며 진입하고, 내려찍은 후 체력을 회복하며 싸우세요. 스웨인이 궁극기를 쓰기 전에 (W)\'공포의 귀환\'으로 거리 조절을 하며 정글러를 기다리는 것도 좋은 방법이에요.', item: '맬모셔스의 아귀를 첫 코어로 선택해 마법 저항력을 높이고 생명선 보호막으로 생존력을 챙기세요. 신발은 (E)\'속박명령\'의 속박 지속시간을 줄여주는 헤르메스의 발걸음이 적절해요.', spell: '점멸과 점화를 추천해요. 스웨인은 (P)\'굶주린 새떼\'와 (R)\'악의 승천\'으로 계속 회복하므로 점화로 회복량을 줄여야 해요.' },
    '스카너': { lv1: '1~2레벨에는 스카너가 (Q)\'부서진 대지/지반 돌출\'로 던지는 바위를 조심하며 거리를 유지하세요. (Q)\'다르킨의 글레이브\'를 사용하여 짧게 딜교환을 하고 체력을 회복하며 결심 중첩을 쌓는 것이 중요해요.', lv3: '3레벨 이후에는 스카너가 (E)\'이쉬탈의 격돌\'로 돌진하여 벽에 부딪히게 만들려 할 때 (E)\'찬란한 쇄도\'를 사용하여 위치를 옮기세요. 스카너가 (W)\'대지의 수호자\'로 보호막을 사용하면 (W)\'공포의 귀환\'으로 대응하며 딜교환을 시도해요.', lv6: '6레벨 이후 스카너가 (R)\'꿰뚫기\'로 제압을 시도하면 대응하기 어려우니 미리 거리를 두어 피해야 해요. 스카너의 스킬이 빠진 타이밍에 (R)\'단호한 판결\'로 내려찍으며 체력을 회복하고 공격적인 플레이를 하세요.', item: '헤르메스의 발걸음과 갈라진 하늘을 선택하세요. 헤르메스의 발걸음으로 스카너의 둔화와 기절 지속시간을 줄이고 갈라진 하늘을 통해 전투 중 체력을 회복해요.', spell: '점멸과 점화를 사용하세요. 점멸로 스카너의 (E)\'이쉬탈의 격돌\'을 피하고 점화로 적의 체력을 낮추어 확실하게 처치하세요.' },
    '신지드': { lv1: '신지드가 (Q)\'맹독의 자취\'를 남겨 지속 피해를 주니 독구름 위를 피하며 거리를 유지하세요. (Q)\'다르킨의 글레이브\'를 사용하여 적을 공격하며 체력을 회복하고 (P)\'전쟁 단련\' 중첩을 차근차근 쌓으세요. 독구름이 깔린 곳에서 무리하게 미니언을 먹기보다 안전한 위치에서 파밍을 진행해요.', lv3: '신지드가 (W)\'초강력 접착제\'를 사용하면 (E)\'찬란한 쇄도\'를 사용할 수 없으니 접착제가 없는 곳에서 싸우세요. 신지드가 (E)\'던져넘기기\'로 던지려 할 때 (W)\'공포의 귀환\'을 사용하여 신지드를 먼저 끌어당겨 딜교환을 시도하세요. (Q)\'다르킨의 글레이브\'를 재사용하여 신지드를 공중에 띄우면 중첩을 쌓기 좋아요.', lv6: '신지드가 (R)\'광기의 물약\'을 마시면 (Q)\'맹독의 자취\'가 고통스러운 상처를 남기고 신지드의 능력치도 오르니 정면 대결을 피하고 물러나세요. 신지드의 스킬이 빠진 틈을 타 (R)\'단호한 판결\'로 내려찍으며 입힌 피해만큼 체력을 회복하세요. 신지드가 라인을 밀면 (W)\'공포의 귀환\'으로 끌어당겨 정글러와 함께 킬각을 노려보세요.', item: '갈라진 하늘을 첫 코어로 선택하여 전투 지속력을 높이세요. 신지드의 마법 피해와 군중 제어를 견디기 위해 헤르메스의 발걸음을 신으세요.', spell: '점멸과 정화를 추천해요. 신지드의 (E)\'던져넘기기\'로 인한 속박을 정화로 빠르게 풀 수 있어요.' },
    '아이번': { lv1: '(Q)\'덩굴뿌리\'에 맞지 않도록 거리를 유지하며 첫 웨이브를 받아내요. (Q)\'다르킨의 글레이브\'를 활용해 체력을 관리하며 상대의 견제를 견뎌내세요.', lv3: '상대의 (Q)\'덩굴뿌리\'를 피한 뒤 (W)\'공포의 귀환\'으로 적을 끌어당겨 딜교환을 시도하세요. (E)\'보호의 씨앗\'을 맞기 전에 (E)\'찬란한 쇄도\'로 진입하며 (Q)\'다르킨의 글레이브\'를 재사용해 공중으로 띄워요.', lv6: '(R)\'데이지!\'가 소환되면 데이지를 조심하며 정글러의 개입을 유도하세요. (R)\'단호한 판결\'로 적에게 피해를 입히며 체력을 회복하고 킬각을 보세요.', item: '헤르메스의 발걸음과 갈라진 하늘을 선택하세요. 상대의 마법 피해와 군중 제어 효과에 대비하며 전투를 지속하기 위해서예요.', spell: '점멸과 점화를 추천해요. 점멸로 (Q)\'덩굴뿌리\'를 피하며 접근하고 점화로 체력을 낮춰 마무리하세요.' },
    '아지르': { lv1: '아지르가 (Q)\'사막의 맹습\'으로 멀리서 견제하며 거리를 벌리려 해요. (Q)\'다르킨의 글레이브\'를 사용하여 체력을 회복하며 미니언을 챙기며 버티는 것이 중요해요. 상대의 둔화 효과를 조심하며 접근할 타이밍을 노리세요.', lv3: '아지르가 (E)\'신기루\'로 위치를 옮기거나 (W)\'일어나라!\'로 견제할 때를 조심하세요. (W)\'공포의 귀환\'으로 적을 끌어당긴 뒤 (Q)\'다르킨의 글레이브\'를 재사용하여 공중에 띄우면 좋아요. (E)\'찬란한 쇄도\'로 빠르게 접근하여 딜교환을 시도하세요.', lv6: '아지르가 (R)\'황제의 진영\'으로 멀리 밀어낼 수 있으니 진입할 때 주의해야 해요. (R)\'단호한 판결\'을 사용하여 적을 내려찍으며 체력을 회복하고 전투를 이어가세요. 상대의 (E)\'신기루\' 보호막이 빠진 상태에서 (W)\'공포의 귀환\'을 연계하면 효과적이에요.', item: '헤르메스의 발걸음과 갈라진 하늘을 추천해요. 아지르의 마법 피해를 견디기 위해 헤르메스의 발걸음을 사고, 첫 기본 공격이 치명타가 되고 체력을 회복하는 갈라진 하늘을 선택하세요.', spell: '점멸과 점화를 추천해요. 점멸로 거리를 좁힌 뒤 (W)\'공포의 귀환\'을 연계하고 점화로 마무리하세요.' },
    '아칼리': { lv1: '아칼리가 (Q)\'오연투척검\'으로 둔화를 걸고 (P)\'암살자의 표식\' 원을 넘나들며 강화 평타를 노려요. (Q)\'다르킨의 글레이브\'로 빠르게 공격해 체력을 회복하며 맞딜을 하되, 너무 깊이 들어가지 마세요. 아칼리의 기력이 빠질 때까지 거리 조절을 하며 천천히 압박하세요.', lv3: '(W)\'황혼의 장막\' 안의 아칼리는 대상 지정이 안 되니 (E)\'찬란한 쇄도\'처럼 범위 피해를 주는 스킬로 대응하세요. 아칼리가 (E)\'표창곡예\'로 진입하면 (W)\'공포의 귀환\'으로 끌어당겨 연계를 끊어주세요. (Q)\'다르킨의 글레이브\'를 재사용해 적을 공중에 띄우면 아칼리의 이동을 멈추고 일방적으로 공격할 수 있어요.', lv6: '아칼리가 (R)\'무결처형\'의 두 번째 돌진으로 마무리하려 하니 체력이 낮을 때는 각별히 주의하세요. (R)\'단호한 판결\'을 사용해 받는 피해를 줄이며 진입하되, 연막 안의 아칼리는 기본 공격 대상으로 지정할 수 없으니 평타로 이어지는 (Q)\'다르킨의 글레이브\'는 연막이 걷힌 뒤에 쓰세요. 라인을 밀어 넣고 아칼리가 포탑 쪽으로 끌려오게 유도해 정글의 도움을 받으세요.', item: '맬모셔스의 아귀를 가서 아칼리의 강력한 마법 피해를 견디고 생명선 보호막으로 버티세요. 신발은 마법 저항력을 높이고 둔화 지속시간을 줄여주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 점화로 아칼리의 체력을 깎아 빠르게 마무리하는 것이 좋아요.' },
    '아크샨': { lv1: '상대의 (Q)\'복수의 부메랑\' 사거리를 고려해 무리하게 앞으로 나가지 말고 거리 조절을 해요. 1~2레벨에는 무리하게 진입하지 말고 (Q)\'다르킨의 글레이브\'로 체력을 회복하며 버티세요. 상대의 평타 견제를 최소화하며 경험치만 챙기는 것이 좋아요.', lv3: '상대가 (E)\'영웅의 비상\'으로 들어올 때 (W)\'공포의 귀환\'으로 적을 끌어당겨 흐름을 끊어주세요. (E)\'찬란한 쇄도\'로 빠르게 접근한 뒤 (Q)\'다르킨의 글레이브\'의 두 번째 사용 효과로 상대를 공중에 띄워 딜교환을 해요. 상대의 (Q)\'복수의 부메랑\'이 돌아오는 경로에서 벗어나며 피해를 줄이세요.', lv6: '체력이 낮을 때 아크샨의 (R)\'인과응보\'에 맞지 않도록 주의하고 거리 조절을 하세요. (R)\'단호한 판결\'을 사용하여 피해를 줄이며 진입하고 체력을 회복해 킬각을 잡으세요. 정글러가 올 때 (W)\'공포의 귀환\'으로 적을 끌어당겨 확실하게 처치해요.', item: '판금 장화와 칠흑의 양날 도끼를 가세요. 판금 장화로 기본 공격 피해를 줄이고, 칠흑의 양날 도끼의 체력과 방어력 감소 효과로 지속 전투를 이어가기 위해서예요.', spell: '점멸과 순간이동을 추천해요. 빠른 라인 복귀와 합류가 중요하기 때문이에요.' },
    '아트록스': { lv1: '아트록스는 (Q)\'다르킨의 검\' 끝자락에 맞으면 공중에 띄워지니 거리를 잘 유지하세요. 1~2레벨에는 (Q)\'다르킨의 글레이브\'로 딜교환을 하며 체력을 회복하고 아트록스의 (Q)\'다르킨의 검\' 사용을 유도하세요. (P)\'전쟁 단련\' 중첩을 쌓으면서 안정적으로 성장하는 것이 중요해요.', lv3: '아트록스가 (W)\'지옥사슬\'을 쓰면 범위 밖으로 빠르게 벗어나서 끌려가지 않도록 주의하세요. 아트록스가 (E)\'파멸의 돌진\'으로 들어올 때 (W)\'공포의 귀환\'을 사용해 아트록스를 끌어당기거나 (E)\'찬란한 쇄도\'로 거리를 좁히세요. 아트록스의 (Q)\'다르킨의 검\'이 모두 소모된 시점에 (Q)\'다르킨의 글레이브\'의 재사용 효과로 공중에 띄우며 딜교환을 하세요.', lv6: '아트록스가 (R)\'세계의 종결자\'를 사용하여 공격력과 회복량이 늘어나면 정면 싸움은 피하는 게 좋아요. (R)\'단호한 판결\'을 사용해 아트록스에게 피해를 입히면 체력을 회복하며 맞대응할 수 있어요. 아트록스가 처치 관여로 궁극기 지속시간을 늘리지 못하도록 정글러를 부르거나 라인 관리에 신경 쓰세요.', item: '첫 코어 아이템은 갈라진 하늘을 가고 신발은 판금 장화로 선택하세요. 아트록스의 물리 피해를 줄이고 전투 중에 체력을 유지하기 위해서예요. 이 아이템들은 전투 지속력을 높여줘요.', spell: '점멸과 점화를 추천해요. 점화로 아트록스의 (P)\'사신 태세\'와 (E)\'파멸의 돌진\'에 의한 체력 회복을 억제할 수 있어요. 상대의 회복을 깎는 것이 핵심이에요.' },
    '암베사': { lv1: '암베사는 (P)\'용사냥개의 발걸음\'으로 스킬 사용 후 빠르게 접근해 공격하니 거리를 잘 유지하세요. (Q)\'교활한 휩쓸기\'의 외곽 피해를 피하며 (Q)\'다르킨의 글레이브\'로 짧게 딜교환하고 체력을 회복하며 버티세요. 암베사가 무리하게 진입할 때 평타로 중첩을 쌓으며 압박하세요.', lv3: '암베사가 (W)\'배척\'으로 보호막을 켜고 준비할 때는 공격을 멈춰 피해량이 늘어나는 것을 막으세요. (E)\'찢어 가르기\'의 둔화에 걸리기 전에 (E)\'찬란한 쇄도\'로 위치를 잡고 (W)\'공포의 귀환\'으로 암베사를 끌어당겨 흐름을 끊으세요. (Q)\'다르킨의 글레이브\'의 재사용 효과로 적을 공중에 띄워 암베사의 돌진 타이밍을 뺏으세요.', lv6: '(R)\'공개 처형\'은 저지 불가 상태로 순간 이동해 제압하니 체력이 낮을 때는 사거리 안에 오래 머물지 마세요. 제압 중에는 스킬을 쓸 수 없으니 (R)\'단호한 판결\'은 암베사가 궁극기를 쓰기 전에 써서 체력을 회복하고 반격하세요. 정글러가 올 때 (W)\'공포의 귀환\'으로 적을 아군 쪽으로 끌어와 빠르게 처리하세요.', item: '판금 장화를 신어 암베사의 기본 공격 피해를 줄이세요. 갈라진 하늘을 첫 코어로 선택해 체력을 보충하고 강력한 첫 타격으로 교전을 주도하세요.', spell: '점멸과 점화를 추천해요. 암베사가 (R)\'공개 처형\'의 패시브로 회복하는 양을 줄이고 확실하게 킬각을 잡으세요.' },
    '애니비아': { lv1: '애니비아는 (Q)\'냉기 폭발\'을 발사해 적을 둔화시키고 기절시킬 수 있으니 구체의 궤적을 잘 살펴야 해요. 구체가 빠진 타이밍에 (Q)\'다르킨의 글레이브\'를 사용하여 접근하면 체력을 회복하며 교환할 수 있어요. 초반에는 거리를 조절하며 애니비아의 스킬을 피하는 것에 집중하세요.', lv3: '애니비아가 (W)\'결정화\'로 길을 막으면 접근이 어려우니 벽이 사라질 때까지 기다려야 해요. (Q)\'냉기 폭발\'이 쿨타임일 때 (W)\'공포의 귀환\'으로 애니비아를 끌어당긴 뒤 (Q)\'다르킨의 글레이브\'를 재사용해 공중에 띄우면 좋아요. (E)\'동상\'은 냉각 상태인 적에게 피해가 커지니 구체에 맞은 직후에는 거리를 두세요.', lv6: '애니비아의 (R)\'얼음 폭풍\' 안에서는 둔화 때문에 움직이기 힘드니 폭풍 밖에서 싸우는 것이 좋아요. (R)\'단호한 판결\'로 날아올라 피해를 입히고 체력을 회복하며 교전하세요. 애니비아가 쓰러지면 (P)\'환생\'으로 알이 되어 살아나니 알을 빠르게 공격해 완전히 처치해야 해요.', item: '갈라진 하늘을 첫 코어로 가서 전투 지속력을 높이세요. 신발은 애니비아의 마법 피해를 줄이기 위해 헤르메스의 발걸음을 추천해요.', spell: '점멸과 정화를 추천해요. (Q)\'냉기 폭발\'의 기절을 정화로 빠르게 풀 수 있어요.' },
    '야스오': { lv1: '야스오는 (Q)\'강철 폭풍\'을 두 번 중첩시켜 회오리를 날리니 1~2레벨에는 중첩이 쌓이지 않도록 거리를 조절하세요. (Q)\'다르킨의 글레이브\'를 사용해 첫 타격을 입히고 체력을 회복하며 파밍에 집중하세요. 야스오가 (E)\'질풍검\'으로 미니언을 타고 들어오면 (W)\'공포의 귀환\'으로 대응하세요.', lv3: '(W)\'바람 장막\'은 투사체만 막으니 기본 공격을 강화하는 (Q)\'다르킨의 글레이브\'나 주변을 가르는 (E)\'찬란한 쇄도\'는 막히지 않아요. (Q)\'강철 폭풍\' 회오리가 날아올 때 (W)\'공포의 귀환\'으로 야스오를 끌어당기며 딜교환을 시작하세요. (Q)\'다르킨의 글레이브\'를 재사용해 야스오를 공중에 띄우면 (E)\'찬란한 쇄도\'로 추가 피해를 입히기 좋아요.', lv6: '야스오의 (R)\'최후의 숨결\'은 공중에 뜬 적에게만 쓸 수 있으니 (Q)\'강철 폭풍\' 회오리만 피해도 궁극기 연계를 막을 수 있어요. (R)\'단호한 판결\'로 입힌 피해량에 따라 체력을 회복할 수 있으니 교전 중에 적절히 사용하세요. 야스오가 (E)\'질풍검\'으로 미니언을 타고 도망가려 하면 (W)\'공포의 귀환\'으로 끌어당기며 라인을 관리하세요.', item: '첫 코어 아이템으로 갈라진 하늘을 선택해 공격력과 체력을 확보하세요. 신발은 야스오의 기본 공격 피해를 줄여 주는 판금 장화가 적절해요.', spell: '점멸과 점화를 추천해요. 점화의 지속 고정 피해로 야스오의 체력을 깎아 킬각을 잡으세요.' },
    '오공': { lv1: '오공은 (Q)\'파쇄격\'으로 사거리를 늘려 견제하며 (P)\'바위 피부\'로 전투 중 방어력을 높여요. (Q)\'다르킨의 글레이브\'로 짧게 치고 빠지며 체력을 회복하고 (P)\'전쟁 단련\' 중첩을 쌓으세요. 오공과 오래 붙어 있으면 상대가 더 단단해지니 주의하세요.', lv3: '(E)\'근두운 급습\'으로 들어오는 오공에게 (W)\'공포의 귀환\'을 써서 거리를 조절하거나 흐름을 끊으세요. (W)\'분신 전사\'로 투명해지며 빠지려 할 때 (E)\'찬란한 쇄도\'로 빠르게 추격해 딜교환을 이어가세요. 상대의 돌진기가 빠진 시점을 노려 공격하세요.', lv6: '(R)\'회전격\'에 맞으면 공중에 떠서 스킬을 쓸 수 없으니 오공이 휘두르기 시작하면 빠르게 피하세요. (R)\'단호한 판결\'을 사용해 내려찍으며 피해를 입히고 체력을 회복하며 킬각을 잡으세요. 오공의 궁극기가 빠진 후 (W)\'공포의 귀환\'으로 끌어당기면 쉽게 제압할 수 있어요.', item: '갈라진 하늘을 첫 코어로 선택해 체력과 공격력을 챙기고 교전 시 유지력을 높이세요. 신발은 오공의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 오공은 (P)\'바위 피부\'로 방어력이 계속 오르니 점화의 추가 피해로 빠르게 처치하세요.' },
    '오로라': { lv1: '오로라가 (Q)\'이중 저주\'를 사용해 멀리서 견제하면 에너지가 되돌아오는 경로를 옆으로 피해 주세요. (Q)\'다르킨의 글레이브\'를 활용해 기본 공격으로 체력을 회복하며 끈질기게 버티는 것이 중요해요. 초반 구간에는 너무 깊게 들어가지 말고 거리 조절에 집중하세요.', lv3: '오로라가 (E)\'마법의 문\'으로 둔화를 걸고 뒤로 도약하면, 곧바로 (W)\'공포의 귀환\'으로 끌어당겨 거리를 좁히세요. (W)\'장막 너머로\'를 사용해 투명 상태가 되면 무리하게 쫓지 말고 다시 모습을 드러낼 때까지 기다려 주세요. (E)\'찬란한 쇄도\'의 가장자리 피해를 활용해 오로라의 체력을 깎아 내세요.', lv6: '오로라의 (R)\'세계의 경계\' 영역은 드나들 때 둔화되고 오로라만 건너편으로 점프할 수 있으니 영역 가장자리에서 싸우지 말고 위치를 살피세요. (R)\'단호한 판결\'로 뛰어들어 받는 피해를 줄이며 체력을 회복해 보세요. 오로라가 (W)\'장막 너머로\'로 도망치기 전에 (Q)\'다르킨의 글레이브\' 재사용 효과로 공중에 띄워 킬각을 잡으세요.', item: '갈라진 하늘을 가서 강력한 한 방 피해와 체력 회복으로 버티세요. 신발은 오로라의 마법 피해를 줄이고 둔화 지속시간을 줄여주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 오로라가 (P)\'영혼 방호술\'을 통해 계속 체력을 회복하므로 점화로 이를 억제해야 해요.' },
    '오른': { lv1: '오른이 (Q)\'용암 균열\'로 둔화를 걸고 기둥을 만들면 기둥이 생길 위치를 미리 보고 피하세요. 1~2레벨에는 (Q)\'다르킨의 글레이브\'로 체력을 회복하며 짧게 딜교를 하세요. 오른의 (Q)\'용암 균열\'이 빠진 타이밍에 (E)\'찬란한 쇄도\'로 접근하는 것이 좋아요.', lv3: '오른이 (W)\'불꽃 풀무질\'로 불안정 상태를 만들면 기본 공격에 밀려날 수 있으니 조심하세요. (W)\'공포의 귀환\'으로 오른을 끌어당긴 뒤 (Q)\'다르킨의 글레이브\'를 재사용해 공중에 띄우면 딜교환이 편해져요. 오른의 (E)\'화염 돌진\'이 벽에 부딪혀 띄우는 것을 조심하며 거리를 조절하세요.', lv6: '오른이 (R)\'대장장이 신의 부름\'을 쓰면 정령이 지나가는 경로를 확인하고 피하세요. (R)\'단호한 판결\'로 내려찍으며 체력을 회복하고 (W)\'공포의 귀환\'을 사용해 킬각을 노려보세요. 오른의 궁극기가 빠진 뒤에 정글러와 함께 압박하면 라인을 밀어넣을 수 있어요.', item: '삼위일체를 첫 코어로 가서 공격력과 스킬 가속을 챙기세요. 신발은 오른의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 오른은 탱커라 킬을 내기 어려우니 점화로 최대한 압박하세요.' },
    '올라프': { lv1: '올라프가 (Q)\'역류\'를 던져 방어력과 이동 속도를 깎으면 거리를 벌리며 대응하세요. (Q)\'다르킨의 글레이브\'를 사용해 두 번 공격하며 체력을 회복하는 것이 중요해요. 올라프의 체력이 낮을수록 (P)\'광전사의 분노\'로 인해 공격 속도가 빨라지니 주의하세요.', lv3: '올라프가 (W)\'버티기\'를 사용해 보호막을 얻었을 때는 무리하게 딜교하지 마세요. (W)\'공포의 귀환\'으로 적을 끌어당기려 하기보다 (E)\'찬란한 쇄도\'를 활용해 거리 조절을 먼저 하세요. 올라프의 (Q)\'역류\'가 빠진 타이밍을 노려 짧게 싸우는 것이 좋아요.', lv6: '올라프가 (R)\'라그나로크\'를 사용하면 이동 방해 효과에 면역이 되어 (Q)\'다르킨의 글레이브\'로 공중에 띄울 수 없어요. (R)\'단호한 판결\'로 체력을 회복하며 버티되 궁극기 지속 시간 동안은 정면 교환을 피하세요. 올라프의 궁극기가 끝나기 전에 라인을 관리하며 정글러의 합류를 기다리세요.', item: '판금 장화와 갈라진 하늘을 추천해요. 판금 장화는 올라프의 기본 공격 피해를 줄여주고 갈라진 하늘은 공격력과 체력을 제공해 전투를 지속하게 도와줘요.', spell: '점멸과 점화를 추천해요. 점화로 (P)\'광전사의 분노\'와 (E)\'무모한 강타\'를 통한 체력 회복을 억제하세요.' },
    '요네': { lv1: '요네는 (Q)\'필멸의 검\'을 맞히면 돌풍으로 띄워 올리니, 중첩이 쌓였다면 거리를 벌려 돌진을 피하세요. (Q)\'다르킨의 글레이브\'를 활용해 짧게 평타를 주고 체력을 회복하며 (P)\'사냥꾼의 길\' 마법 피해를 최소화하세요. 시작 웨이브에서는 무리하게 붙지 말고 거리 조절을 하며 결심 중첩을 쌓으세요.', lv3: '(E)\'영혼해방\'을 사용한 요네가 다시 육신으로 돌아오는 지점을 예측해 (W)\'공포의 귀환\'으로 끌어당겨 딜교환을 시작하세요. 요네가 (W)\'영혼 가르기\'로 보호막을 얻었을 때는 공격을 잠시 멈추고 (E)\'찬란한 쇄도\'로 범위를 벗어나는 것이 좋아요. (Q)\'필멸의 검\' 돌풍이 빠진 타이밍에 (Q)\'다르킨의 글레이브\' 재사용으로 상대를 띄워 공격하세요.', lv6: '요네의 (R)\'운명봉인\'은 경로의 적을 끌어당기니, 아군과 일직선으로 서 있지 말고 빠르게 옆으로 피하세요. (R)\'단호한 판결\'을 사용해 내려찍으며 피해를 입히고 체력을 회복해 요네의 지속 딜을 버텨내세요. 라인을 당겨 두고 아군 정글러가 오면 (W)\'공포의 귀환\'으로 요네를 끌어당겨 함께 공격하세요.', item: '갈라진 하늘을 초반 코어로 선택해 체력을 보충하고 타격 시 체력 회복으로 유지력을 높이세요. 신발은 요네의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. (W)\'영혼 가르기\' 보호막이 사라진 뒤 점화로 확실하게 마무리 피해를 입히세요.' },
    '요릭': { lv1: '요릭이 (Q)\'최후의 의식\'을 사용하여 미니언을 처치하며 무덤을 쌓지 못하게 견제하세요. (Q)\'다르킨의 글레이브\'를 사용해 체력을 회복하며 근접전에서 맞서면 초반 교환을 잘 해낼 수 있어요. 요릭의 (E)\'애도의 안개\'가 날아올 때 거리를 조절하며 무덤이 쌓이기 전에 싸움을 유도하세요.', lv3: '요릭이 (W)\'망자의 진\'으로 길을 막으면 벽은 공격을 받으면 파괴되니 평타로 부수고 진입하세요. (E)\'애도의 안개\' 표식이 남은 상태에서 요릭의 망령이 달려들면 (E)\'찬란한 쇄도\'로 돌진하며 주변 피해를 입히고 거리를 벌리세요. (Q)\'다르킨의 글레이브\'를 재사용하여 요릭을 공중에 띄워 흐름을 끊는 것이 중요해요.', lv6: '요릭이 (R)\'군도의 장송곡\'으로 안개 마녀를 소환하면 안개 마녀의 표적이 되지 않도록 주의하며 (R)\'단호한 판결\'로 빠르게 내려찍으세요. (R)\'단호한 판결\'을 통해 입힌 피해로 체력을 회복하며 안개 마녀와 망령을 상대하는 것이 좋아요. 요릭이 마녀와 함께 라인을 밀 때는 무리하게 싸우기보다 정글러를 불러 함께 압박하세요.', item: '판금 장화와 갈라진 하늘을 추천해요. 판금 장화로 요릭의 기본 공격 피해를 줄이고 갈라진 하늘로 전투 유지력을 높이세요.', spell: '점멸과 점화를 추천해요. 요릭이 (Q)\'최후의 의식\'으로 체력을 회복하는 것을 점화로 억제하며 킬을 노릴 수 있어요.' },
    '우디르': { lv1: '우디르가 (Q)\'야생 발톱\' 태세를 사용하여 기본 공격을 강화하면 초반 교전이 매우 강력해요. 1~2레벨에는 우디르가 (E)\'불길 쇄도\'로 돌진해 기절을 맞히지 않도록 거리를 조절하며 (Q)\'다르킨의 글레이브\'로 체력을 회복하세요. 우디르의 강화된 평타가 끝나길 기다리며 미니언을 챙기세요.', lv3: '우디르가 (W)\'강철 갑옷\'을 사용하여 보호막과 회복을 얻는 타이밍에는 무리하게 진입하지 마세요. (E)\'불길 쇄도\'의 기절이 빠진 것을 확인한 후 (W)\'공포의 귀환\'으로 우디르를 끌어당기며 싸우세요. (Q)\'다르킨의 글레이브\'를 재사용하여 우디르를 공중에 띄우면 훨씬 안정적으로 딜을 넣을 수 있어요.', lv6: '우디르가 (R)\'날개 돋친 폭풍\'을 켜고 둔화를 걸며 다가올 때는 (E)\'찬란한 쇄도\'를 활용해 위치를 잡으세요. 우디르가 (E)\'불길 쇄도\'를 재사용해 이동 불가 효과에 면역이 된 상태라면 (W)\'공포의 귀환\' 사용을 자제해야 해요. (R)\'단호한 판결\'로 내려찍어 체력을 회복하며 우디르의 폭풍이 사라진 뒤에 몰아붙이세요.', item: '판금 장화와 갈라진 하늘을 추천해요. 우디르의 강력한 기본 공격 피해를 줄이고 전투 시 체력을 회복하며 싸워야 해요.', spell: '점멸과 점화를 선택하세요. 점화로 우디르의 (W)\'강철 갑옷\'을 통한 체력 회복 효과를 줄이며 킬각을 잡으세요.' },
    '우르곳': { lv1: '우르곳은 (Q)\'부식성 폭약\'으로 둔화를 걸고 (P)\'화염의 메아리\'로 견제하니 폭약의 낙하지점을 피해 거리 조절을 하세요. (Q)\'다르킨의 글레이브\'의 체력 회복을 활용해 소모전을 버티며 평타로 결심 중첩을 쌓으세요. 무리하게 진입하기보다 짧게 교환하고 빠지는 리듬을 유지하세요.', lv3: '(E)\'경멸\'에 맞으면 우르곳 뒤로 던져지며 기절하니, 돌진 경로에서 비켜나거나 스킬이 빠진 것을 확인하고 진입하세요. (W)\'심판의 원\'이 켜졌을 때는 정면 승부를 피하고 (E)\'찬란한 쇄도\'의 외곽 피해를 입히며 빠르게 빠져나오세요. (W)\'공포의 귀환\'으로 우르곳을 끌어당긴 뒤 (Q)\'다르킨의 글레이브\' 재사용으로 띄워 빠르게 피해를 입히세요.', lv6: '(R)\'불사의 공포\' 섬광탄에 맞은 상태에서 체력이 낮아지면 제압당해 처형될 수 있으니 주의하세요. 상대의 처형 가능 체력 이하로 내려가기 전에 (R)\'단호한 판결\'로 내려찍어 체력을 회복하고 피해를 입히세요. (E)\'찬란한 쇄도\'로 진입한 뒤 (W)\'공포의 귀환\' 연계로 정글러의 호응을 유도하면 쉽게 킬각을 잡을 수 있어요.', item: '갈라진 하늘을 첫 코어로 선택해 체력과 공격력을 챙기고 교전 중 체력을 회복하세요. 신발은 우르곳의 기본 공격 피해를 줄이고 방어력으로 물리 피해를 견디게 해 주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화의 추가 피해를 더해 우르곳의 (R)\'불사의 공포\' 처형선에 닿기 전에 빠르게 처치하세요.' },
    '워윅': { lv1: '워윅은 (Q)\'야수의 송곳니\'로 도약하며 체력을 회복하니 1~2레벨에 무리하게 맞붙지 마세요. (Q)\'다르킨의 글레이브\'로 두 번 공격하며 체력을 회복해 교환 손해를 줄이세요. 워윅의 체력이 낮아지면 (P)\'끝없는 허기\'로 회복량이 늘어나니 주의하세요.', lv3: '워윅이 (E)\'원시의 포효\'를 사용하면 받는 피해가 줄어드니 그 타이밍에는 (E)\'찬란한 쇄도\'로 거리를 조절하세요. (W)\'공포의 귀환\'으로 워윅을 끌어당겨 (Q)\'다르킨의 글레이브\'의 재사용 효과를 맞히는 것이 중요해요. 워윅의 (E)\'원시의 포효\'가 끝나기 전까지는 딜교환을 아끼는 게 좋아요.', lv6: '워윅의 (R)\'무한의 구속\'은 제압 효과라 정화로 풀 수 없으니 정글러가 근처에 있다면 조심하세요. (R)\'단호한 판결\'을 사용해 체력을 회복하며 싸우되 워윅의 제압에 걸리지 않도록 주의해야 해요. 워윅의 (W)\'피의 사냥\'에 감지되지 않게 체력 관리를 하며 라인을 유지하세요.', item: '첫 코어로 갈라진 하늘을 선택하세요. 신발은 워윅의 마법 피해와 (E)\'원시의 포효\' 공포 지속시간을 줄여주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 점화로 워윅의 (Q)\'야수의 송곳니\'와 (P)\'끝없는 허기\'를 통한 회복량을 줄이세요.' },
    '이렐리아': { lv1: '이렐리아는 (Q)\'칼날 쇄도\'로 미니언을 타며 빠르게 접근하고 체력을 회복해요. 미니언 체력이 낮은 쪽에 서 있지 말고, (Q)\'다르킨의 글레이브\'의 회복력을 이용해 짧게 딜교환하세요. (P)\'아이오니아의 열정\' 중첩이 쌓이면 공격 속도가 빨라지니 장기전은 피하세요.', lv3: '(E)\'쌍검협무\'의 두 칼날이 모이는 위치를 피해 기절과 표식을 허용하지 마세요. 표식이 남으면 (Q)\'칼날 쇄도\'가 초기화되어 계속 쫓아오니 거리 조절이 중요해요. 상대가 (W)\'저항의 춤\'을 충전하는 동안은 받는 물리 피해가 줄어드니 교환을 아끼고, 발사된 뒤 (W)\'공포의 귀환\'으로 끌어당겨 (E)\'찬란한 쇄도\'로 피해를 입히세요.', lv6: '(R)\'선봉진격검\'의 결계 안에서 둔화되면 (Q)\'칼날 쇄도\'의 타겟이 되기 쉬우니 빠르게 벗어나세요. (R)\'단호한 판결\'을 사용해 날아오르는 동안 피해를 줄이고, 내려찍은 뒤 (Q)\'다르킨의 글레이브\'의 재사용 효과로 상대를 공중에 띄워 흐름을 제어하세요. 정글러가 올 때 (W)\'공포의 귀환\'으로 적을 아군 쪽으로 끌어당기면 킬각을 잡기 편해요.', item: '삼위일체를 첫 코어로 가서 공격력과 체력을 동시에 챙겨 (Q)\'칼날 쇄도\'의 돌진을 버티세요. 신발은 이렐리아의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 (Q)\'칼날 쇄도\'의 체력 회복을 억제하고 마무리 피해를 입히세요.' },
    '일라오이': { lv1: '일라오이는 (P)\'고대신의 예언자\'로 지형 근처에서 촉수 공격을 하니 벽에서 떨어져 싸우세요. (Q)\'다르킨의 글레이브\'로 체력을 회복하며 딜교환을 하고, 일라오이가 (Q)\'촉수 강타\'를 헛치게 유도하세요.', lv3: '(E)\'영혼의 시험\'에 맞으면 영혼이 분리되니 영혼에서 너무 멀어져 숙주가 되지 않도록 주의하세요. (W)\'혹독한 가르침\'으로 도약해 들어올 때 (W)\'공포의 귀환\'으로 끌어당겨 위치를 바꾸거나 (E)\'찬란한 쇄도\'로 빠르게 빠져나오세요.', lv6: '(R)\'믿음의 도약\'은 피해를 입은 적 챔피언 한 명당 촉수를 소환하니 즉시 범위를 벗어나세요. 촉수는 한동안 대상으로 지정할 수 없으니 무리하게 잡으려 하지 말고, 사라진 뒤에 (R)\'단호한 판결\'로 내려찍어 피해를 입히고 체력을 회복하며 킬각을 잡으세요.', item: '판금 장화와 갈라진 하늘을 추천해요. 판금 장화로 일라오이의 기본 공격 피해를 줄이고 갈라진 하늘의 체력과 회복으로 버티며 싸우세요.', spell: '점멸과 점화를 추천해요. 점화의 지속 고정 피해로 (R)\'믿음의 도약\' 이후 범위를 벗어나려는 일라오이를 마무리하세요.' },
    '자크': { lv1: '자크의 (Q)\'탄성 주먹\'은 맞으면 붙잡히고 조각이 생기니 맞지 않게 거리 조절을 하세요. 1~2레벨에는 자크의 스킬을 피하며 (Q)\'다르킨의 글레이브\'로 체력을 회복하며 맞대응하세요. 자크가 조각을 흡수하기 전에 평타로 압박하여 체력 차이를 만드세요.', lv3: '자크가 (E)\'새총 발사\'로 날아올 때 (E)\'찬란한 쇄도\'를 사용하여 위치를 옮기거나 거리를 벌리세요. 자크의 (Q)\'탄성 주먹\'을 피한 뒤 (W)\'공포의 귀환\'으로 자크를 끌어당겨 딜교환을 시작하세요. 자크가 (W)\'불안정 물질\'을 쓰기 전에 (Q)\'다르킨의 글레이브\' 재사용으로 공중에 띄우는 것이 중요해요.', lv6: '자크가 (R)\'바운스!\'로 여러 번 튀어 올라 공중에 띄울 때 스킬 사용이 제한되니 주의하세요. 자크의 체력이 낮을 때 (R)\'단호한 판결\'로 내려찍어 피해를 입히고 체력을 회복하며 조각을 정리하세요. 자크가 (P)\'세포 분열\'로 부활할 가능성이 있으니 (R)\'단호한 판결\' 이후 남은 체력을 확실히 깎아야 해요.', item: '첫 코어로 공격력과 체력을 모두 제공하는 삼위일체를 올리세요. 신발은 자크의 마법 피해와 군중 제어 지속시간을 줄여주는 헤르메스의 발걸음을 선택하세요.', spell: '점멸과 점화를 추천해요. 점화로 자크가 (P)\'세포 분열\'을 활용해 회복하는 것을 억제하세요.' },
    '잭스': { lv1: '1~2레벨에는 (Q)\'다르킨의 글레이브\'를 사용하여 적의 체력을 깎으며 체력을 관리하세요. 잭스가 (Q)\'도약 공격\'으로 들어오며 (W)\'무기 강화\' 평타를 칠 때 거리를 조절하는 것이 중요해요. 초반에는 짧은 교환 위주로 진행하며 (P)\'전쟁 단련\' 중첩을 쌓으세요.', lv3: '잭스가 (E)\'반격\'을 사용하면 기본 공격이 모두 회피되고 끝날 때 주변을 기절시키니 그동안은 평타를 멈추고 범위 밖으로 물러나세요. (E)\'반격\'이 끝난 직후 (Q)\'다르킨의 글레이브\'의 재사용 효과로 잭스를 공중에 띄우면 딜교환을 주도할 수 있어요. 잭스의 (Q)\'도약 공격\' 타이밍을 예측하여 (W)\'공포의 귀환\'으로 끌어당겨 흐름을 끊으세요.', lv6: '잭스가 (R)\'무기의 달인\'을 사용해 방어력을 높이면 정면 싸움이 힘들어지니 (R)\'단호한 판결\'의 방어구 관통력 효과를 활용하세요. 잭스가 (Q)\'도약 공격\'으로 진입할 때 (W)\'공포의 귀환\'으로 끌어당겨 역공을 펼치며 (R)\'단호한 판결\'로 체력을 회복하세요. 잭스가 궁극기를 켜고 몰아붙일 때는 (E)\'찬란한 쇄도\'로 주변에 피해를 입히며 대응하세요.', item: '첫 코어로 삼위일체를 선택하여 공격력과 스킬 가속을 챙기세요. 신발은 잭스의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 마무리 피해를 더해 잭스를 처치하세요.' },
    '제이스': { lv1: '제이스가 캐논 형태의 (Q)\'전격 폭발\'로 멀리서 견제할 때 투사체 궤적을 피해 비스듬히 다가가세요. (Q)\'다르킨의 글레이브\'를 사용해 빠르게 공격하고 체력을 회복하며 상대의 초반 견제를 견뎌내세요.', lv3: '(E)\'가속 관문\'을 통과한 (Q)\'전격 폭발\'은 사거리가 매우 길어지니 관문이 설치되면 직선에서 빠르게 벗어나세요. (E)\'천둥 강타\'에 밀려나기 전에 (E)\'찬란한 쇄도\'로 파고들고, (W)\'공포의 귀환\'으로 제이스를 끌어당겨 딜교환을 시도하세요.', lv6: '제이스가 (R)\'머큐리 캐논\'으로 변환해 방어력을 깎는 기본 공격을 조심하세요. (R)\'머큐리 해머\'로 변환해 방어력이 높아진 상태에서는 무리하지 말고, (R)\'단호한 판결\'로 진입해 피해를 입히고 체력을 회복하며 킬각을 잡으세요.', item: '갈라진 하늘을 선택해 체력을 보충하고 적중 시 체력 회복 효과로 유지력을 높이세요. 신발은 제이스의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 순간이동을 추천해요. 제이스의 강한 견제로 인해 라인 복귀가 중요하므로 순간이동을 사용하여 손해를 줄이세요.' },
    '초가스': { lv1: '1~2레벨에는 (Q)\'파열\'의 범위 표시를 확인하고 빠르게 벗어나 공중에 뜨지 않도록 주의하세요. (Q)\'다르킨의 글레이브\'를 사용해 짧은 평타 교환으로 체력을 회복하며 압박하세요. (E)\'날카로운 가시\'의 둔화 효과가 계속 묻으면 거리 조절이 어려우니 너무 오래 붙어 있지 마세요.', lv3: '(W)\'흉포한 울부짖음\'에 침묵되면 스킬을 쓸 수 없으니 초가스가 먼저 비명을 지른 후에 진입하세요. (E)\'찬란한 쇄도\'로 파고든 뒤 (W)\'공포의 귀환\'으로 상대를 끌어당겨 강하게 공격하세요. (Q)\'다르킨의 글레이브\'를 재사용해 상대를 공중에 띄우면 초가스의 반격을 억제하며 딜교환을 마칠 수 있어요.', lv6: '(R)\'포식\'은 방어력을 무시하는 고정 피해를 입히니 체력이 낮을 때 무리하게 접근하지 마세요. (R)\'단호한 판결\'을 사용하면 날아오르는 동안 피해량이 감소하고 내려찍으며 체력을 회복할 수 있어 생존에 도움이 돼요. 초가스가 (Q)\'파열\'을 헛방 친 순간이 (E)\'찬란한 쇄도\'로 진입해 킬각을 잡기 가장 좋은 타이밍이에요.', item: '최대 체력이 높은 적에게 효과적인 몰락한 왕의 검을 첫 코어로 선택하세요. 신발은 마법 저항력을 높이고 (W)\'흉포한 울부짖음\'의 침묵과 (Q)\'파열\'의 둔화 지속시간을 줄여주는 헤르메스의 발걸음이 좋아요.', spell: '점멸과 점화를 추천해요. 점화로 (P)\'육식\'을 통한 초가스의 체력 회복을 억제하고 킬각을 잡으세요.' },
    '카밀': { lv1: '카밀은 (Q)\'정확성 프로토콜\'로 강화 평타를 치며 (P)\'적응형 방어 체계\'로 보호막을 얻어요. 1~2레벨에는 (Q)\'다르킨의 글레이브\'로 짧게 딜교환하며 체력을 회복하고, 카밀이 (Q)\'정확성 프로토콜\'의 두 번째 강화 공격을 준비할 때 거리를 벌리세요. 보호막이 생성된 상태에서는 오래 싸우지 말고 짧게 치고 빠지세요.', lv3: '(W)\'전술적 휩쓸기\'의 바깥쪽 절반에 맞으면 둔화되고 카밀이 회복하니, 원뿔 안쪽으로 파고들거나 완전히 피하세요. 카밀이 (E)\'갈고리 발사\'로 진입할 때 (W)\'공포의 귀환\'으로 끌어당겨 흐름을 끊거나 (E)\'찬란한 쇄도\'로 위치를 옮기세요. (Q)\'다르킨의 글레이브\'의 재사용 효과로 카밀을 공중에 띄워 흐름을 끊으세요.', lv6: '(R)\'마법공학 최후통첩\'에 갇히면 탈출할 수 없으니 체력이 낮을 때는 카밀의 궁극기 사거리 안에 들어가지 마세요. 궁극기에 갇혔다면 (R)\'단호한 판결\'로 내려찍어 큰 피해를 입히고 체력을 회복하며 버티세요. 라인 관리 중 (E)\'갈고리 발사\'를 이용한 기습 진입을 조심하고 정글러가 오면 (E)\'찬란한 쇄도\'로 빠르게 합류하세요.', item: '판금 장화와 칠흑의 양날 도끼를 추천해요. 판금 장화로 (Q)\'정확성 프로토콜\'의 평타 피해를 줄이고, 칠흑의 양날 도끼의 체력과 방어력 감소 효과로 카밀의 방어력을 깎으세요.', spell: '점멸과 점화를 추천해요. 점화로 (W)\'전술적 휩쓸기\'의 회복 효과를 억제하고 킬각을 잡으세요.' },
    '카사딘': { lv1: '(Q)\'무의 구체\' 견제를 조심하며 (Q)\'다르킨의 글레이브\'로 체력을 회복하며 버티세요. (P)\'전쟁 단련\' 중첩을 쌓기 위해 짧은 딜교환을 시도하며 거리를 조절해요.', lv3: '(E)\'찬란한 쇄도\'로 빠르게 접근한 뒤 (W)\'공포의 귀환\'으로 상대를 끌어당겨 딜교환을 시작해요. 상대의 (E)\'힘의 파동\'이 빠진 것을 확인하고 (Q)\'다르킨의 글레이브\' 재사용으로 공중에 띄워 확실하게 피해를 입히세요.', lv6: '(R)\'단호한 판결\'로 진입해 강력한 피해를 주고 체력을 회복하며 킬각을 잡으세요. 상대가 (R)\'균열 이동\'으로 스킬을 피하기 쉬우니 신중하게 사용하고, 정글러가 오기 전 라인을 적절히 유지해요.', item: '헤르메스의 발걸음과 맬모셔스의 아귀를 가요. 마법 저항력을 높여 (W)\'황천의 검\' 피해를 줄이고 생명선 보호막으로 생존력을 높이기 위해서예요.', spell: '점멸과 점화를 추천해요. (R)\'균열 이동\'이 없는 초반에 확실한 킬각을 잡고 피해량을 극대화하기 위해서예요.' },
    '카시오페아': { lv1: '(Q)\'맹독 폭발\'의 견제를 최소화하며 경험치 위주로 행동하세요. (Q)\'다르킨의 글레이브\'를 활용해 짧은 딜교환 후 체력을 회복하며 버티는 것이 중요해요. 첫 웨이브부터 너무 깊게 들어가지 말고 거리 조절에 집중하세요.', lv3: '(W)\'독기의 늪\'이 깔려 있을 때는 (E)\'찬란한 쇄도\'를 절대 사용하지 말고 기다리세요. 상대가 스킬을 낭비한 틈을 타 (W)\'공포의 귀환\'으로 끌어당긴 뒤 (Q)\'다르킨의 글레이브\' 재사용으로 띄우면 강하게 압박할 수 있어요. (E)\'쌍독니\'의 지속적인 피해를 줄이기 위해 빠르게 진입하고 빠지세요.', lv6: '(R)\'석화의 응시\'에 기절하지 않도록 카시오페아를 등지는 방향으로 움직이세요. (R)\'단호한 판결\'을 사용해 공중에서 피해를 줄이며 진입한 뒤 강력한 일격을 날려 킬각을 잡으세요. 라인을 밀 때는 정글 개입에 대비해 (E)\'찬란한 쇄도\'를 아껴두는 것이 좋아요.', item: '헤르메스의 발걸음과 맬모셔스의 아귀를 추천해요. 마법 저항력을 높여 (E)\'쌍독니\' 피해를 줄이고 생명선 보호막으로 생존력을 높여야 해요.', spell: '점멸과 정화를 추천해요. (R)\'석화의 응시\' 기절이나 (W)\'독기의 늪\' 둔화 상태를 즉시 풀고 진입하기 위해서예요.' },
    '케넨': { lv1: '케넨은 (Q)\'천둥의 표창\'으로 멀리서 표식을 남기며 견제해요. 표식이 가득 쌓이면 기절하니 거리를 조절하며 미니언을 챙기세요. (Q)\'다르킨의 글레이브\'를 사용하여 체력을 회복하며 안정적으로 대응하세요.', lv3: '케넨이 (E)\'번개 질주\'로 진입할 때 표식이 쌓이는 것을 경계하세요. 케넨의 (W)\'전류 방출\'이 빠졌을 때 (W)\'공포의 귀환\'으로 적을 끌어당기고 (Q)\'다르킨의 글레이브\'를 다시 사용해 공중에 띄우며 딜교환을 하세요. (E)\'찬란한 쇄도\'를 활용해 케넨의 (Q)\'천둥의 표창\' 사거리를 잘 피하며 움직이세요.', lv6: '케넨이 (R)\'날카로운 소용돌이\'를 사용하면 주변에 마법 피해를 입히니 주의하세요. 궁극기가 끝나는 시점에 (R)\'단호한 판결\'로 내려찍어 피해를 입히고 체력을 회복하며 역습하세요. 케넨의 스킬이 빠진 타이밍에 정글러와 함께 압박하는 것이 좋아요.', item: '갈라진 하늘을 첫 코어로 가서 전투 지속력을 높이세요. 신발은 마법 저항력과 강인함을 제공하는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 정화를 추천해요. 케넨의 (P)\'폭풍의 표식\'으로 걸리는 기절은 정화로 풀 수 있어요.' },
    '케일': { lv1: '케일은 (P)\'거룩한 승천\'이 쌓이기 전인 초반 구간이 약한 구간이에요. (Q)\'광휘의 일격\'은 처음 맞힌 적과 그 뒤의 적까지 맞히니 미니언 뒤에 숨기보다 궤적에서 비켜서세요. (Q)\'다르킨의 글레이브\'로 빠르게 체력을 회복하고 첫 웨이브부터 평타를 쳐서 결심 중첩을 쌓는 것이 중요해요.', lv3: '(Q)\'광휘의 일격\'에 맞으면 방어력이 낮아지니, 스킬이 빠진 타이밍에 (E)\'찬란한 쇄도\'로 빠르게 진입하세요. 진입 후 (W)\'공포의 귀환\'으로 끌어당겨 딜교환을 이어가고, (E)\'화염주문검\'의 강한 추가 피해를 피하기 위해 체력이 너무 낮아지기 전에 거리를 조절하세요. (W)\'천상의 축복\'으로 도망가는 케일을 끝까지 추격해 압박을 유지하세요.', lv6: '(R)\'신성한 심판\'의 무적 효과가 지속되는 동안에는 공격이 통하지 않으니, 무적이 끝나는 시점을 정확히 노려 (R)\'단호한 판결\'로 내려찍으세요. 상대의 궁극기가 빠진 뒤 (W)\'공포의 귀환\'과 (Q)\'다르킨의 글레이브\' 재사용의 공중에 띄우기를 연계해 킬각을 잡으세요. 정글러와 함께 진입해 케일이 무적을 쓰기 전에 빠르게 제압하세요.', item: '몰락한 왕의 검을 가서 공격 속도와 생명력 흡수로 지속 싸움을 이끄세요. 신발은 케일의 마법 피해와 (Q)\'광휘의 일격\'의 둔화 지속시간을 줄여주는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. (W)\'천상의 축복\'의 회복량을 줄이고 초반에 빠르게 킬을 따내 케일의 성장을 늦추세요.' },
    '코그모': { lv1: '코그모가 (Q)\'부식성 침\'을 사용하면 미니언 뒤에 서서 첫 번째 대상이 챔피언이 되지 않도록 피해를 줄이세요. (Q)\'다르킨의 글레이브\'로 미니언을 챙기며 체력을 회복하고 성장에 집중해요. 상대의 사거리가 길기 때문에 무리하게 다가가기보다는 거리를 유지하며 파밍해요.', lv3: '코그모가 (W)\'생체마법 폭격\'을 켜고 거리를 벌리면 (E)\'찬란한 쇄도\'를 사용하여 빠르게 접근하세요. (E)\'공허의 분비물\'이 남긴 흔적을 밟아 이동 속도가 느려지지 않도록 조심해야 해요. (W)\'공포의 귀환\'으로 적을 끌어당긴 뒤 (Q)\'다르킨의 글레이브\'를 재사용하여 공중에 띄우며 딜교환을 해요.', lv6: '코그모가 (R)\'살아있는 곡사포\'를 사용해 멀리서 공격하면 체력 관리에 신경 쓰며 라인을 관리해요. (R)\'단호한 판결\'로 날아올라 코그모에게 피해를 입히고 체력을 회복하며 킬을 노려보세요. 곡사포로 내 위치가 드러나기 전에 정글러를 호출하거나 빠르게 전투를 마무리해요.', item: '헤르메스의 발걸음과 갈라진 하늘을 가세요. 코그모의 마법 피해를 견디기 위해 마법 저항력이 필요하고 갈라진 하늘로 전투를 지속해요.', spell: '점멸과 점화를 추천해요. 점멸로 코그모에게 순식간에 접근하고 점화로 마무리 피해를 입히세요.' },
    '코르키': { lv1: '(Q)\'인광탄\' 견제가 심하므로 거리 조절을 하며 체력을 보존하세요. (Q)\'다르킨의 글레이브\'를 사용해 미니언을 빠르게 잡으면서 체력을 회복하고 진입 기회를 엿보세요. 무리하게 다가가지 말고 상대의 스킬이 빠지는 타이밍을 기다리는 것이 중요해요.', lv3: '(E)\'찬란한 쇄도\'로 빠르게 접근한 뒤 (W)\'공포의 귀환\'으로 상대를 끌어당겨 딜교환을 시도하세요. 상대가 (W)\'발키리\'로 도망가기 전에 (Q)\'다르킨의 글레이브\'를 재사용해 공중에 띄워 확실한 피해를 입히는 것이 좋아요. (E)\'개틀링 건\'에 노출되는 시간을 줄이기 위해 빠르게 진입하고 빠지세요.', lv6: '(R)\'단호한 판결\'의 피해 감소 효과를 활용해 상대의 (R)\'미사일 폭격\' 피해를 견디며 진입하세요. (R)\'단호한 판결\'로 내려찍은 후 (W)\'공포의 귀환\'과 연계하면 킬각을 잡기 편해요. 라인을 밀어넣고 정글러를 호출하여 상대가 (W)\'발키리\'를 사용하기 전에 함께 덮치세요.', item: '발걸음 분쇄기와 헤르메스의 발걸음을 추천해요. 발걸음 분쇄기의 파괴의 충격파 둔화와 이동 속도 증가로 접근 능력을 높이고 헤르메스의 발걸음의 마법 저항력으로 견제를 버티세요.', spell: '점멸과 순간이동을 추천해요. (W)\'발키리\'로 도망치는 상대를 추격하거나 빠르게 복귀하여 라인 손실을 줄여야 해요.' },
    '퀸': { lv1: '퀸은 (P)\'매사냥\' 표식을 이용한 원거리 견제가 강하니 (Q)\'다르킨의 글레이브\'를 활용해 체력을 관리하며 버티세요. 퀸의 (Q)\'실명 공격\'에 맞아 시야가 좁아지면 대응하기 어려우니 주의하며 거리 조절을 해야 해요. 1~2레벨 구간에서는 무리하게 싸우기보다 미니언을 챙기며 기회를 보세요.', lv3: '퀸이 (E)\'공중제비\'를 사용해 뒤로 물러나면 (W)\'공포의 귀환\'을 사용하여 다시 끌어당겨 딜교환을 이어가세요. 퀸의 (Q)\'실명 공격\'을 피하면서 (E)\'찬란한 쇄도\'로 빠르게 접근하는 것이 중요해요. 퀸이 (E)\'공중제비\'로 거리를 벌리기 전에 스킬을 맞혀야 해요.', lv6: '퀸이 (R)\'후방 지원\'을 사용해 이동할 때는 무리하게 따라가지 말고 라인을 관리하며 정글러를 부르세요. 퀸이 강습할 때 (R)\'단호한 판결\'을 사용해 피해를 줄이고 체력을 회복해야 해요. 퀸이 착지한 직후 (W)\'공포의 귀환\'으로 거리를 좁히면 킬각을 잡기에 좋아요.', item: '판금 장화와 삼위일체를 추천해요. 판금 장화는 퀸의 기본 공격 피해를 줄여주며 삼위일체는 공격력과 체력을 동시에 챙겨줘요.', spell: '점멸과 점화를 추천해요. 점멸로 퀸에게 접근하고 점화로 체력이 낮은 퀸을 마무리하세요.' },
    '크산테': { lv1: '크산테는 (Q)\'엔토포 타격\'으로 둔화를 걸고 두 번 적중시켜 적을 끌어당기려 해요. (Q)\'다르킨의 글레이브\'로 체력을 회복하며 짧게 딜교환하고, 상대의 두 번째 충격파가 오기 전에 거리를 벌리세요. 1~2레벨에는 평타 위주로 견제하며 결심 중첩을 쌓으세요.', lv3: '(W)\'길을 여는 자\'는 저지 불가 돌진이라 막을 수 없으니, 상대가 기를 모으는 동안은 (W)\'공포의 귀환\'을 아끼고 옆으로 피하세요. (E)\'발놀림\'으로 보호막을 얻으며 들어오는 타이밍에 (E)\'찬란한 쇄도\'의 가장자리 마법 피해를 입히며 거리를 조절하세요. 상대의 기절 스킬이 빠진 뒤에 (Q)\'다르킨의 글레이브\' 재사용으로 공중에 띄워 일방적으로 공격하세요.', lv6: '(R)\'총공세\'를 사용한 크산테는 방어력이 낮아지지만 피해량과 공격 속도가 크게 늘어나니 정면 승부는 피하고 짧게 치고 빠지세요. 크산테의 (R)\'총공세\'에 밀려나기 전에 (R)\'단호한 판결\'로 먼저 날아올라 피해를 줄이고 체력을 회복하세요. (R)\'총공세\' 중에는 최대 체력과 추가 방어력이 줄어드니 정글러가 합류했다면 이때 집중 공격해 킬각을 잡으세요.', item: '몰락한 왕의 검을 첫 코어로 가서 체력이 높은 크산테에게 효율적인 피해를 입히고 생명력 흡수로 버티세요. 신발은 크산테의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. (R)\'총공세\' 상태에서 크산테의 체력 회복량을 줄여 확실하게 제압할 수 있어요.' },
    '클레드': { lv1: '(Q)\'덫날리기\'에 붙잡힌 채 클레드와 가까이 있으면 끌려가며 추가 피해를 입으니 즉시 거리를 벌리세요. 첫 웨이브부터 (Q)\'다르킨의 글레이브\'로 스칼의 체력을 깎으며 체력을 회복하세요. 무리하게 다가가지 말고 평타 위주로 대응하세요.', lv3: '클레드가 (E)\'이랴!\'로 돌진해올 때 (W)\'공포의 귀환\'을 사용해 적을 끌어당기고 (Q)\'다르킨의 글레이브\' 재사용으로 공중에 띄우세요. (W)\'버럭버럭\'이 활성화되어 공격 속도가 빨라진 동안은 평타 교환을 피하고 뒤로 물러나세요. (E)\'찬란한 쇄도\'는 클레드의 (Q)\'덫날리기\'가 빠진 것을 확인한 뒤 진입할 때 사용하세요.', lv6: '(R)\'돌겨어어억!!!\'을 사용할 때는 보호막과 함께 빠르게 돌진하며 밀어내므로 일직선상에서 벗어나세요. 클레드가 스칼에서 내린 상태라면 챔피언 피해량이 줄어드니 (R)\'단호한 판결\'로 내려찍어 체력을 회복하며 처치하세요. 클레드가 스칼을 다시 타기 전에 정글러와 함께 압박해 마무리하세요.', item: '판금 장화와 갈라진 하늘을 가세요. 판금 장화로 (W)\'버럭버럭\'의 기본 공격 피해를 줄이고 갈라진 하늘의 라이트실드 타격 효과로 생존력과 피해량을 높이세요.', spell: '점멸과 점화를 추천해요. 스칼에서 내린 클레드는 스칼의 보호를 받지 못하므로 점화의 추가 피해로 빠르게 처치하기 좋아요.' },
    '탐켄치': { lv1: '탐 켄치는 (Q)\'혀 채찍\'으로 견제하며 (P)\'절대 미각\' 중첩을 쌓으니 미니언 뒤에 서서 공격을 막아내세요. (Q)\'다르킨의 글레이브\'를 사용하여 평타와 함께 짧게 교환하며 체력을 관리하세요. 중첩이 세 번 쌓이기 전에 거리를 유지하며 성장에 집중하는 것이 좋아요.', lv3: '탐 켄치의 (W)\'심연 잠수\'가 나타날 위치를 확인하고 범위 밖으로 벗어나 공중으로 띄우는 효과를 피하세요. (E)\'두꺼운 피부\'로 보호막을 만든 상태라면 피해를 주기보다 보호막이 사라질 때까지 기다렸다가 (W)\'공포의 귀환\'으로 끌어당기세요. (E)\'찬란한 쇄도\'의 가장자리를 맞히면 최대 체력 비례 피해를 입힐 수 있어요.', lv6: '(P)\'절대 미각\' 중첩이 세 번 쌓이면 (R)\'집어삼키기\'에 먹혀 큰 피해를 입으니 중첩이 쌓이지 않게 주의하세요. 탐 켄치의 체력이 높을 때는 (R)\'단호한 판결\'로 내려찍으며 피해를 입히고 체력을 회복하며 전투를 이어가세요. (Q)\'혀 채찍\'이 빠진 것을 확인한 뒤 (W)\'공포의 귀환\'으로 끌어당겨 짧게 교환하고 빠지세요.', item: '몰락한 왕의 검을 첫 코어로 선택해 체력이 높은 탐 켄치에게 효과적인 피해를 입히세요. 신발은 탐 켄치의 마법 피해를 줄이는 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. 점화로 탐 켄치의 (Q)\'혀 채찍\'과 (E)\'두꺼운 피부\'에 의한 체력 회복을 억제하세요.' },
    '트런들': { lv1: '트런들은 (Q)\'깨물기\'로 공격력을 흡수하고 둔화를 걸며 1~2레벨 구간에서 강해요. (Q)\'깨물기\'를 맞았다면 무리하게 싸우지 말고 (Q)\'다르킨의 글레이브\'로 체력을 회복하며 거리를 조절하세요. 트런들은 (P)\'헌납\'으로 미니언이 죽을 때 체력을 회복하니 미니언 근처에서는 싸움을 피하세요.', lv3: '트런들이 (W)\'얼음 왕국\'을 사용하면 영역 안에서 공격 속도와 이동 속도가 오르니 밖에서 교환하세요. (E)\'얼음 기둥\'에 맞으면 뒤로 밀려나고 둔화를 얻으니 (W)\'공포의 귀환\'을 사용하여 트런들을 당겨오세요. (Q)\'다르킨의 글레이브\'를 재사용하여 트런들을 공중에 띄우며 짧게 딜교하세요.', lv6: '트런들이 (R)\'진압\'으로 체력과 방어력 및 마법 저항력을 훔치면 능력이 돌아올 때까지 뒤로 빠지세요. (R)\'단호한 판결\'의 피해 감소 효과를 이용해 진입하고 입힌 피해만큼 체력을 회복하며 싸우세요. 트런들은 (P)\'헌납\' 때문에 미니언이 쓰러지는 구간에서 체력을 회복하므로 킬각을 잡을 때 주의하세요.', item: '판금 장화를 신발로 선택해 트런들의 (Q)\'깨물기\'를 포함한 기본 공격 피해를 줄이세요. 첫 코어 아이템으로는 갈라진 하늘을 구매해 체력과 공격력을 챙기고 전투 중 회복력을 높이세요.', spell: '점멸과 점화를 추천해요. 점화의 체력 회복 감소 효과로 트런들의 (P)\'헌납\'과 치유를 억제하며 마무리하세요.' },
    '트린다미어': { lv1: '트린다미어는 (E)\'회전 베기\'로 빠르게 접근해 평타를 치려 하니 적절한 거리를 유지하세요. (Q)\'다르킨의 글레이브\'를 사용해 체력을 회복하며 짧게 피해를 입히고 빠지는 것이 좋아요. (Q)\'피의 갈망\' 효과로 체력이 낮을 때 공격력이 올라가니 무리하게 끝내려 하지 말고 신중하게 행동하세요.', lv3: '(W)\'조롱의 외침\'에 맞았을 때 바로 등을 돌려 도망치면 둔화되니 주의하며 (E)\'찬란한 쇄도\'로 위치를 잡으세요. (Q)\'다르킨의 글레이브\'를 재사용해 트린다미어를 공중에 띄우면 순간적으로 공격 흐름을 끊을 수 있어요. 이어지는 (W)\'공포의 귀환\'으로 상대를 끌어당겨 피해를 입히고 빠르게 거리를 벌리세요.', lv6: '트린다미어가 (R)\'불사의 분노\'를 켜면 죽지 않으니 그동안은 피해를 최소화하며 버티세요. 궁극기 지속시간이 끝나는 시점에 맞춰 (R)\'단호한 판결\'로 내려찍어 마무리하는 것이 중요해요. (E)\'회전 베기\'로 진입하는 경로를 예측해 거리 조절을 하고 정글러의 도움을 받아 처리하세요.', item: '갈라진 하늘을 첫 코어로 가서 체력과 공격력을 챙기고 교전 중 체력을 회복하세요. 신발은 트린다미어의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. 트린다미어는 (Q)\'피의 갈망\'으로 체력을 회복하므로 점화의 치유 감소 효과가 매우 효율적이에요.' },
    '티모': { lv1: '티모가 (E)\'맹독 다트\'를 묻히며 평타로 괴롭히니 무리하게 맞붙지 말고 거리를 조절하세요. 만약 (Q)\'실명 다트\'에 맞으면 평타로 (P)\'전쟁 단련\' 중첩을 쌓기 어려우니 뒤로 빠져서 대기해요. (Q)\'다르킨의 글레이브\'를 찍었다면 적절한 타이밍에 사용해 체력을 회복하며 버티는 것이 좋아요.', lv3: '티모의 (Q)\'실명 다트\'가 빠진 것을 확인한 뒤에 (E)\'찬란한 쇄도\'를 사용해 빠르게 접근하세요. 접근한 뒤에는 (W)\'공포의 귀환\'으로 티모를 끌어당겨서 (Q)\'다르킨의 글레이브\'로 공중에 띄우고 딜교환을 해요. 티모가 (W)\'신속한 이동\'으로 도망가면 (E)\'찬란한 쇄도\'로 거리를 좁혀 보되 무리해서 쫓지는 마세요.', lv6: '(R)\'유독성 함정\'이 깔린 길목은 밟으면 이동 속도가 느려지니 조심하며 라인을 관리하세요. 티모가 모습을 드러내면 (R)\'단호한 판결\'로 내려찍어 피해를 입히고 체력을 회복하며 킬을 노려보세요. (W)\'공포의 귀환\'으로 티모를 내 쪽으로 끌어오면 (R)\'단호한 판결\'을 맞히기가 훨씬 수월해요.', item: '삼위일체를 첫 코어로 올려 전투 지속력을 높이세요. 신발은 티모의 마법 피해를 견디기 위해 헤르메스의 발걸음을 추천해요.', spell: '점멸과 점화를 추천해요. (Q)\'실명 다트\'는 대상 지정이라 피할 수 없으니 이 스킬이 빠진 뒤 점멸로 붙어 (W)\'공포의 귀환\'을 맞히고 점화로 마무리하세요.' },
    '판테온': { lv1: '판테온은 (Q)\'혜성의 창\'으로 견제하며 (P)\'필멸자의 의지\'를 쌓아 다음 스킬을 강화해요. (Q)\'다르킨의 글레이브\'로 체력을 회복하며 버티고, 강화된 스킬이 나가기 전까지는 적절한 거리를 유지하세요. 무리하게 붙기보다 상대의 스킬 쿨타임을 확인하며 짧게 딜교환을 하세요.', lv3: '판테온이 (W)\'방호의 도약\'으로 기절시키면 스킬을 쓸 수 없으니, 상대의 도약이 빠진 것을 확인하고 (W)\'공포의 귀환\'으로 끌어당기세요. (E)\'방패 돌격\'을 사용하는 동안은 정면 피해에 면역이므로 스킬을 쏟지 말고, 효과가 끝난 뒤 (E)\'찬란한 쇄도\'로 진입하세요. 기절에 걸리기 전에 빠르게 움직여 스킬을 피하는 것이 중요해요.', lv6: '판테온이 (R)\'거대 유성\'을 사용해 사라지면 다른 라인 합류나 기습을 의심하고 빠르게 대처하세요. 상대의 진입 스킬이 빠진 타이밍에 (R)\'단호한 판결\'로 내려찍어 피해를 입히고 체력을 회복하세요. (W)\'방호의 도약\'에 걸려 정글러에게 노출되지 않도록 라인 관리와 시야 확보에 신경 쓰세요.', item: '갈라진 하늘과 판금 장화를 추천해요. 갈라진 하늘로 체력과 공격력을 챙기며 유지력을 높이고, 판금 장화로 판테온의 기본 공격 피해를 줄이세요.', spell: '점멸과 정화를 추천해요. (W)\'방호의 도약\'에 의한 기절을 정화로 빠르게 풀어 추가 피해를 차단하세요.' },
    '피들스틱': { lv1: '1~2레벨에는 상대가 (Q)\'공포\'를 사용하기 위해 시야 밖에서 대기하는지 확인하며 거리를 조절해요. (Q)\'다르킨의 글레이브\'를 활용해 미니언과 함께 체력을 회복하며 라인을 유지하세요. 무리한 진입보다는 (P)\'전쟁 단련\' 중첩을 쌓으며 성장에 집중하는 것이 좋아요.', lv3: '상대의 (E)\'수확\' 중심부에 맞으면 침묵에 걸려 스킬을 쓸 수 없으니 범위 가장자리에 위치하도록 주의해요. (W)\'풍작\'의 정신 집중을 끊기 위해 (Q)\'다르킨의 글레이브\'의 재사용 효과로 상대를 공중에 띄우세요. 상대의 (E)\'수확\'이 빠진 뒤 (W)\'공포의 귀환\'을 사용해 딜교환을 진행해요.', lv6: '상대가 (R)\'까마귀 폭풍\'으로 진입할 때 (R)\'단호한 판결\'의 피해 감소 효과를 사용하여 버티며 대응하세요. 부쉬에서 (Q)\'공포\'를 맞지 않도록 시야 확보에 신경 쓰며 플레이해요. 라인을 관리하며 아군 정글러와 함께 상대를 압박하는 구도를 만드세요.', item: '헤르메스의 발걸음과 맬모셔스의 아귀를 추천해요. 마법 저항력을 높이고 (Q)\'공포\'나 (E)\'수확\'의 군중 제어 지속 시간을 줄이기 위해서예요.', spell: '점멸과 점화를 추천해요. (W)\'풍작\'의 체력 회복 효과를 감소시키고 킬 각을 잡기 위해서예요.' },
    '피오라': { lv1: '피오라는 (Q)\'찌르기\'로 거리를 좁히며 압박하고 (P)\'치명적인 검무\'의 급소를 노리려 해요. (Q)\'다르킨의 글레이브\'를 사용하여 체력을 회복하며 버티고 급소 방향이 아닌 곳으로 움직이세요. 1~2레벨에는 무리하게 싸우기보다 미니언을 챙기며 피오라의 (Q)\'찌르기\' 쿨타임을 확인하세요.', lv3: '피오라가 (W)\'응수\'를 사용하면 받는 공격과 이동 불가 효과를 막아내고 검을 찌르니, (W)\'공포의 귀환\'이나 (Q)\'다르킨의 글레이브\'를 쓰기 전에 (W)\'응수\'가 빠졌는지 확인하세요. 피오라의 (W)\'응수\'가 빠진 것을 확인한 뒤에 (W)\'공포의 귀환\'으로 적을 끌어당겨 딜교환을 시작하세요. 피오라가 (E)\'대가의 검술\'로 강화 평타를 쓰기 전에 거리를 조절하며 대응하세요.', lv6: '피오라가 (R)\'대결투\'를 사용해 급소를 노리면 체력 회복과 이동 속도 상승으로 매우 강력해져요. (R)\'단호한 판결\'로 피해를 입히며 체력을 회복하되 피오라가 급소를 모두 맞히지 못하도록 주의하세요. 피오라가 급소를 가격해 주변 아군까지 치유하지 못하도록 라인 주도권을 유지하며 싸우세요.', item: '갈라진 하늘을 첫 코어로 올려 전투 지속력을 높이세요. 신발은 피오라의 기본 공격 피해를 줄여주는 판금 장화가 좋아요.', spell: '점멸과 점화를 추천해요. (P)\'치명적인 검무\'로 피오라가 체력을 회복하는 것을 점화로 억제하세요.' },
    '하이머딩거': { lv1: '하이머딩거는 (Q)\'H-28 G 진화형 포탑\'을 설치해 라인을 장악하며 포탑 주변에서 이동 속도가 올라가요. 포탑 사거리 안에서 계속 머물기보다는 (Q)\'다르킨의 글레이브\'를 활용해 체력을 회복하며 짧게 교환하세요. 포탑이 설치되는 동안에는 무리하게 진입하지 말고 거리를 유지하며 대응하세요.', lv3: '(E)\'CH-2 전자폭풍 수류탄\'의 중심에 맞으면 기절하니 범위를 잘 피해서 움직여야 해요. (W)\'마법공학 초소형 로켓\'이 챔피언에게 적중하면 포탑이 빠르게 충전되니 주의하세요. 하이머딩거가 포탑에 의존할 때 (W)\'공포의 귀환\'으로 끌어당겨서 포탑 밖에서 (Q)\'다르킨의 글레이브\'로 딜교환을 하세요.', lv6: '하이머딩거가 (R)\'업그레이드!!!\'를 사용해 강화된 스킬을 쓰면 매우 위협적이니 주의하세요. 하이머딩거의 포탑이 적을 때 (R)\'단호한 판결\'로 도약해 내려찍으며 킬각을 잡으세요. (E)\'찬란한 쇄도\'로 진입할 때 포탑의 공격에 노출되지 않도록 조심하며 체력을 관리하세요.', item: '헤르메스의 발걸음을 먼저 올려 마법 저항력과 강인함을 확보하세요. 첫 코어 아이템은 갈라진 하늘을 선택해 전투 중에 체력을 회복하며 지속력을 높여요.', spell: '점멸과 점화를 추천해요. 하이머딩거가 포탑을 깔고 버티려 할 때 점화로 빠르게 마무리하세요.' }
  }
};
// 사이트 등록: window.TOP_MATCHUPS['내챔피언_상대'] = { lvl1, lvl3, lvl6, item, spell } (이름의 띄어쓰기는 제거)
(function (d) {
  var g = typeof window !== 'undefined' ? window : globalThis;
  g.TOP_MATCHUPS = g.TOP_MATCHUPS || {};
  var me = d.champion.replace(/\s+/g, '');
  Object.keys(d.matchups).forEach(function (opp) {
    var m = d.matchups[opp];
    g.TOP_MATCHUPS[me + '_' + opp.replace(/\s+/g, '')] = { lvl1: m.lv1, lvl3: m.lv3, lvl6: m.lv6, item: m.item, spell: m.spell };
  });
})(top_zaahen);
if (typeof module !== 'undefined') module.exports = top_zaahen;
